{
  "name": "Slow Life Shopping List",
  "description": "A dual-location shopping list manager for 'Slow Life 1' and 'Slow Life 2' featuring voice input and a master item history.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type LocationId = 'slowlife1' | 'slowlife2';

export interface ShoppingItem {
  id: string;
  name: string;
  completed: boolean;
  createdAt: number;
}

export interface AppState {
  currentLocation: LocationId | null;
  lists: Record<LocationId, ShoppingItem[]>;
  masterHistory: string[];
}

import React, { useState, useEffect, useCallback } from 'react';
import { LocationId, ShoppingItem, AppState } from './types';
import LocationSelector from './components/LocationSelector';
import ShoppingListView from './components/ShoppingListView';

const STORAGE_KEY = 'slow_life_shopping_data';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
    return {
      currentLocation: null,
      lists: {
        slowlife1: [],
        slowlife2: [],
      },
      masterHistory: [],
    };
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string) => {
    const { currentLocation } = state;
    if (!currentLocation || !name.trim()) return;

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.trim(),
      completed: false,
      createdAt: Date.now(),
    };

    setState(prev => {
      const newList = [...prev.lists[currentLocation], newItem];
      const newHistory = Array.from(new Set([...prev.masterHistory, name.trim()]));

      return {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: newList,
        },
        masterHistory: newHistory,
      };
    });
  }, [state.currentLocation]);

  const toggleItem = (id: string) => {
    const { currentLocation } = state;
    if (!currentLocation) return;

    setState(prev => ({
      ...prev,
      lists: {
        ...prev.lists,
        [currentLocation]: prev.lists[currentLocation].map(item =>
          item.id === id ? { ...item, completed: !item.completed } : item
        ),
      },
    }));
  };

  const deleteItem = (id: string) => {
    const { currentLocation } = state;
    if (!currentLocation) return;

    setState(prev => ({
      ...prev,
      lists: {
        ...prev.lists,
        [currentLocation]: prev.lists[currentLocation].filter(item => item.id !== id),
      },
    }));
  };

  const resetList = () => {
    const { currentLocation } = state;
    if (!currentLocation) return;

    if (window.confirm('この拠点のリストをリセットしますか？')) {
      setState(prev => ({
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [],
        },
      }));
    }
  };

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col">
      {!state.currentLocation ? (
        <LocationSelector onSelect={setLocation} />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onDelete={deleteItem}
          onReset={resetList}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ShoppingItem, LocationId } from '../types';
import MasterListModal from './MasterListModal';

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: string[];
  onBack: () => void;
  onAdd: (name: string) => void;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onReset: () => void;
}

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  onBack,
  onAdd,
  onToggle,
  onDelete,
  onReset,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const recognitionRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    // Initialize Speech Recognition if supported
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.lang = 'ja-JP';
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputValue(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => {
        setIsListening(false);
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
      };
    }
  }, []);

  const handleVoiceInput = () => {
    if (!recognitionRef.current) {
      alert('お使いのブラウザは音声入力に対応していません。');
      return;
    }
    if (isListening) {
      recognitionRef.current.stop();
    } else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleAdd = () => {
    if (inputValue.trim()) {
      onAdd(inputValue);
      setInputValue('');
    }
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Header */}
      <header className="px-6 py-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <button onClick={onBack} className="text-gray-400 hover:text-gray-600 p-2 -ml-2">
          <i className="fa-solid fa-chevron-left text-xl"></i>
        </button>
        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold tracking-widest text-gray-400 uppercase">LOCATION</span>
          <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        </div>
        <button onClick={onReset} className="text-red-400 hover:text-red-600 p-2 -mr-2 text-sm font-bold">
          リセット
        </button>
      </header>

      {/* Input Area */}
      <div className="p-6 bg-white shadow-sm space-y-4">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
              placeholder="何を買いますか？"
              className="w-full pl-4 pr-10 py-3 rounded-2xl border-2 border-gray-100 focus:border-gray-200 outline-none transition-all"
            />
            <button
              onClick={handleVoiceInput}
              className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-full transition-colors ${
                isListening ? 'text-red-500 animate-pulse bg-red-50' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              <i className="fa-solid fa-microphone"></i>
            </button>
          </div>
          <button
            onClick={handleAdd}
            style={{ backgroundColor: themeColor }}
            className="w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg active:scale-90 transition-transform"
          >
            <i className="fa-solid fa-plus text-xl"></i>
          </button>
        </div>

        <button
          onClick={() => setShowHistory(true)}
          className="w-full py-2 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200 hover:bg-[#e9e5e0]"
        >
          <i className="fa-solid fa-list-ul"></i>
          リストから選ぶ
        </button>
      </div>

      {/* List Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-300">
            <i className="fa-solid fa-basket-shopping text-4xl mb-4"></i>
            <p className="text-sm">リストは空です</p>
          </div>
        ) : (
          items.map((item) => (
            <div
              key={item.id}
              className={`flex items-center gap-3 p-4 bg-white rounded-2xl shadow-sm border border-gray-100 animate-fadeIn ${
                item.completed ? 'opacity-60' : ''
              }`}
            >
              <button
                onClick={() => onToggle(item.id)}
                className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                  item.completed 
                    ? 'bg-green-500 border-green-500 text-white' 
                    : 'border-gray-200 text-transparent'
                }`}
              >
                <i className="fa-solid fa-check text-xs"></i>
              </button>
              <span 
                className={`flex-1 text-[15px] font-medium transition-all ${
                  item.completed ? 'line-through text-gray-400' : 'text-[#4a3f35]'
                }`}
              >
                {item.name}
              </span>
              <button
                onClick={() => onDelete(item.id)}
                className="text-gray-300 hover:text-red-400 p-2 transition-colors"
              >
                <i className="fa-solid fa-trash-can text-sm"></i>
              </button>
            </div>
          ))
        )}
      </div>

      {/* History Modal */}
      {showHistory && (
        <MasterListModal
          history={masterHistory}
          onSelect={(name) => {
            onAdd(name);
            setShowHistory(false);
          }}
          onClose={() => setShowHistory(false)}
          themeColor={themeColor}
        />
      )}
    </div>
  );
};

export default ShoppingListView;

import React, { useMemo } from 'react';

interface Props {
  history: string[];
  onSelect: (name: string) => void;
  onClose: () => void;
  themeColor: string;
}

const MasterListModal: React.FC<Props> = ({ history, onSelect, onClose, themeColor }) => {
  // Sort by Japanese あいうえお order
  const sortedHistory = useMemo(() => {
    return [...history].sort((a, b) => a.localeCompare(b, 'ja'));
  }, [history]);

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center animate-fadeIn">
      <div 
        className="absolute inset-0 bg-black/40 backdrop-blur-sm" 
        onClick={onClose}
      />

      <div className="relative bg-white w-full max-w-md h-[70vh] rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-slideUp">
        {/* Header */}
        <div className="px-6 py-4 border-b flex items-center justify-between sticky top-0 bg-white z-10">
          <h3 className="text-lg font-bold">過去の履歴から追加</h3>
          <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-100 text-gray-400 flex items-center justify-center">
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4">
          {sortedHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 py-12">
              <i className="fa-solid fa-clock-rotate-left text-4xl mb-4 opacity-20"></i>
              <p>履歴はまだありません</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3">
              {sortedHistory.map((name, index) => (
                <button
                  key={`${name}-${index}`}
                  onClick={() => onSelect(name)}
                  className="p-4 text-left bg-[#fdfaf6] border border-gray-100 rounded-2xl hover:border-gray-200 active:scale-95 transition-all group"
                >
                  <span className="text-sm font-bold text-[#6b5e51] group-hover:text-[#4a3f35]">
                    {name}
                  </span>
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-6 border-t bg-gray-50 text-center text-xs text-gray-400">
          一度入力したアイテムがここに あいうえお順に並びます
        </div>
      </div>
    </div>
  );
};

export default MasterListModal;

