import React, { useState, useRef, useEffect } from 'react';
import { ShoppingItem, LocationId } from '../types';
import MasterListModal from './MasterListModal';

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: string[];
  onBack: () => void;
  onAdd: (name: string) => void;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onReset: () => void;
  onResetApp: () => void;
}

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  onBack,
  onAdd,
  onToggle,
  onDelete,
  onReset,
  onResetApp,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const recognitionRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.lang = 'ja-JP';
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputValue(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, []);

  const handleVoiceInput = () => {
    if (!recognitionRef.current) {
      alert('お使いのブラウザは音声入力に対応していません。');
      return;
    }
    if (isListening) {
      recognitionRef.current.stop();
    } else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleAdd = () => {
    if (inputValue.trim()) {
      onAdd(inputValue);
      setInputValue('');
    }
  };

  return (
    <div className="flex flex-col h-full overflow-hidden relative">
      {/* Header */}
      <header className="px-4 py-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <div className="flex items-center">
          <button onClick={onBack} className="text-gray-400 hover:text-gray-600 p-2">
            <i className="fa-solid fa-chevron-left text-xl"></i>
          </button>
        </div>

        <div className="flex flex-col items-center">
          <span className="text-[10px] font-bold tracking-widest text-gray-400 uppercase">LOCATION</span>
          <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        </div>

        <div className="flex items-center gap-1">
          <button 
            onClick={onReset}
            className="text-red-400 hover:text-red-600 text-sm font-bold px-3 py-1 rounded-full hover:bg-red-50 transition-colors"
          >
