        <button
          onClick={() => setShowHistory(true)}
          className="w-full py-2 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200 hover:bg-[#e9e5e0]"
        >
          <i className="fa-solid fa-list-ul"></i>
          リストから選ぶ
        </button>
      </div>

      {/* List Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
