export default MasterListModal;

import React, { useState, useRef, useEffect } from 'react';
import { ShoppingItem, LocationId } from '../types';
import MasterListModal from './MasterListModal';

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: string[];
  onBack: () => void;
  onAdd: (name: string) => void;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onReset: () => void;
  onResetApp: () => void;
  onDeleteHistoryItem: (name: string) => void;
}

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  onBack,
  onAdd,
  onToggle,
  onDelete,
  onReset,
  onResetApp,
  onDeleteHistoryItem,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [confirmType, setConfirmType] = useState<'list' | 'app' | null>(null);

  const recognitionRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.lang = 'ja-JP';
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputValue(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, []);

  const handleVoiceInput = () => {
    if (!recognitionRef.current) {
      alert('音声入力に対応していません');
      return;
    }
    if (isListening) {
      recognitionRef.current.stop();
    } else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleAdd = () => {
    if (inputValue.trim()) {
      onAdd(inputValue);
      setInputValue('');
    }
  };

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  };

  return (
    <div className="flex flex-col h-full overflow-hidden relative">
      {/* Header */}
      <header className="px-4 py-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <button onClick={onBack} className="text-gray-400 hover:text-gray-600 p-2">
          <i className="fa-solid fa-chevron-left text-xl"></i>
        </button>

        <div className="flex flex-col items-center">
          <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        </div>

        <div className="flex items-center gap-1">
          <button 
            onClick={() => setConfirmType('list')}
            className="text-red-400 hover:text-red-600 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-red-50 transition-all border border-transparent active:border-red-100"
          >
            リセット
          </button>

          <div className="relative">
            <button 
              onClick={() => setShowSettings(!showSettings)} 
              className="text-gray-300 hover:text-gray-500 p-2"
            >
              <i className="fa-solid fa-ellipsis-vertical text-lg"></i>
            </button>

            {showSettings && (
              <div className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-xl border border-gray-100 py-2 z-50 animate-fadeIn">
                <button 
                  onClick={() => { setConfirmType('app'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-gray-400 hover:bg-gray-50 flex items-center gap-3"
                >
                  <i className="fa-solid fa-rotate-left w-4"></i>
                  プロトタイプ１に戻る
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Input Area */}
      <div className="p-6 bg-white shadow-sm space-y-4">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
              placeholder="何を買いますか？"
              className="w-full pl-4 pr-10 py-3 rounded-2xl border-2 border-gray-100 focus:border-gray-200 outline-none transition-all"
            />
            <button
              onClick={handleVoiceInput}
              className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-full transition-colors ${
                isListening ? 'text-red-500 animate-pulse bg-red-50' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              <i className="fa-solid fa-microphone"></i>
            </button>
          </div>
          <button
            onClick={handleAdd}
            style={{ backgroundColor: themeColor }}
            className="w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg active:scale-90 transition-transform"
          >
            <i className="fa-solid fa-plus text-xl"></i>
          </button>
        </div>

        <button
          onClick={() => setShowHistory(true)}
          className="w-full py-2.5 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200 hover:bg-[#e9e5e0] transition-colors"
        >
          <i className="fa-solid fa-list-ul"></i>
          リストから選ぶ
        </button>
      </div>

      {/* List Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-300">
            <i className="fa-solid fa-basket-shopping text-4xl mb-4 opacity-30"></i>
            <p className="text-sm font-bold opacity-50">依頼はありません</p>
          </div>
        ) : (
          items.map((item) => (
            <div
              key={item.id}
              className={`flex items-center gap-3 p-4 bg-white rounded-2xl shadow-sm border border-gray-100 animate-fadeIn ${
                item.completed ? 'opacity-60' : ''
              }`}
            >
              <button
                onClick={() => onToggle(item.id)}
                className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                  item.completed 
                    ? 'bg-green-500 border-green-500 text-white' 
                    : 'border-gray-200 text-transparent'
                }`}
              >
                <i className="fa-solid fa-check text-xs"></i>
              </button>
              <div className="flex-1 flex items-baseline justify-between gap-2">
                <span 
                  className={`text-[15px] font-bold transition-all ${
                    item.completed ? 'line-through text-gray-400 font-normal' : 'text-[#4a3f35]'
                  }`}
                >
                  {item.name}
                </span>
                <span className="text-[10px] text-gray-300 font-normal shrink-0">
                  {formatDate(item.createdAt)}
                </span>
              </div>
              <button
                onClick={() => onDelete(item.id)}
                className="text-gray-200 hover:text-red-400 p-2 transition-colors"
              >
                <i className="fa-solid fa-trash-can text-sm"></i>
              </button>
            </div>
          ))
        )}
      </div>

      {/* Confirmation Dialogs */}
      {confirmType && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-fadeIn">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setConfirmType(null)} />
          <div className="relative bg-white w-full max-w-xs rounded-[32px] p-8 shadow-2xl text-center space-y-6">
            <div className={`w-14 h-14 rounded-full flex items-center justify-center mx-auto ${
              confirmType === 'list' ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-500'
            }`}>
              <i className={`fa-solid ${confirmType === 'list' ? 'fa-trash-can' : 'fa-rotate-left'} text-xl`}></i>
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-800 mb-2">
                {confirmType === 'list' ? 'リストを空にしますか？' : '初期化しますか？'}
              </h3>
              <p className="text-xs text-gray-500 leading-relaxed">
                {confirmType === 'list' 
                  ? `${locationName} の買い物依頼をすべて削除します。` 
                  : '履歴を含むすべてのデータが削除され、プロトタイプ１の状態に戻ります。'}
              </p>
            </div>
            <div className="flex flex-col gap-2">
              <button
                onClick={() => {
                  if (confirmType === 'list') onReset();
                  else onResetApp();
                  setConfirmType(null);
                }}
                className={`w-full py-4 rounded-2xl font-bold text-sm text-white active:scale-95 transition-all ${
                  confirmType === 'list' ? 'bg-red-500 shadow-lg shadow-red-100' : 'bg-gray-800'
                }`}
              >
                {confirmType === 'list' ? 'はい、リセットする' : 'はい、初期化する'}
              </button>
              <button
                onClick={() => setConfirmType(null)}
                className="w-full py-3 bg-transparent text-gray-400 rounded-2xl font-bold text-sm active:scale-95 transition-all"
              >
                キャンセル
              </button>
            </div>
          </div>
        </div>
      )}

      {/* History Modal */}
      {showHistory && (
        <MasterListModal
          history={masterHistory}
          onSelect={(name) => {
            onAdd(name);
            setShowHistory(false);
          }}
          onDeleteHistoryItem={onDeleteHistoryItem}
          onClose={() => setShowHistory(false)}
          themeColor={themeColor}
        />
      )}

      {/* Settings Backdrop */}
      {showSettings && (
        <div className="fixed inset-0 z-40" onClick={() => setShowSettings(false)} />
      )}
    </div>
  );
};

