import React, { useState, useEffect, useCallback } from 'react';
import { LocationId, ShoppingItem, AppState } from './types';
import LocationSelector from './components/LocationSelector';
import ShoppingListView from './components/ShoppingListView';
import LoginScreen from './components/LoginScreen';

const STORAGE_KEY = 'slow_life_shopping_data_prototype_1';
const AUTH_KEY = 'slow_life_auth_v1';

const App: React.FC = () => {
  const initialState: AppState = {
    currentLocation: null,
    lists: {
      slowlife1: [],
      slowlife2: [],
    },
    masterHistory: [],
  };

  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    return localStorage.getItem(AUTH_KEY) === 'true';
  });

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
    return initialState;
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem(AUTH_KEY, 'true');
  };

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation || !name.trim()) return prev;

      const newItem: ShoppingItem = {
        id: crypto.randomUUID(),
        name: name.trim(),
        completed: false,
        createdAt: Date.now(),
      };

      const newList = [...prev.lists[currentLocation], newItem];
      const newHistory = Array.from(new Set([...prev.masterHistory, name.trim()]));

      return {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: newList,
        },
        masterHistory: newHistory,
      };
    });
  }, []);

  const toggleItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      return {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, completed: !item.completed } : item
          ),
        },
      };
    });
  };

  const deleteItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      return {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].filter(item => item.id !== id),
        },
      };
    });
  };

  const resetList = useCallback(() => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;
      return {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [],
        },
      };
    });
  }, []);

  const deleteHistoryItem = useCallback((name: string) => {
    setState(prev => ({
      ...prev,
      masterHistory: prev.masterHistory.filter(item => item !== name),
    }));
  }, []);

  const resetToPrototype1 = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(AUTH_KEY);
    setIsLoggedIn(false);
    setState(initialState);
  }, [initialState]);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
        <LoginScreen onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
      {!state.currentLocation ? (
        <LocationSelector 
          onSelect={setLocation} 
          onResetApp={resetToPrototype1} 
        />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onDelete={deleteItem}
          onReset={resetList}
          onResetApp={resetToPrototype1}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

