import { 
  getFirestore, 
  doc, 
  onSnapshot, 
  setDoc, 
  enableIndexedDbPersistence 
} from 'https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js';
import { LocationId, ShoppingItem, AppState } from './types';
import LocationSelector from './components/LocationSelector';
import ShoppingListView from './components/ShoppingListView';
import LoginScreen from './components/LoginScreen';

/**
 * 【Firebase設定の貼り付け手順】
 * Firebaseコンソールで取得した config の内容を下の {} 内に上書きしてください。
 */
const firebaseConfig = {
  apiKey: "ここに貼り付け",
  authDomain: "ここに貼り付け",
  projectId: "ここに貼り付け",
  storageBucket: "ここに貼り付け",
  messagingSenderId: "ここに貼り付け",
  appId: "ここに貼り付け"
};

// Firebaseの初期化
let db: any = null;
try {
  // YOUR_API_KEY のままではない場合のみ初期化を実行
  if (firebaseConfig.apiKey && firebaseConfig.apiKey !== "YOUR_API_KEY" && firebaseConfig.apiKey !== "ここに貼り付け") {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);

    // オフラインでも使えるようにする設定
    enableIndexedDbPersistence(db).catch((err: any) => {
      if (err.code === 'failed-precondition') {
        console.warn("複数タブが開かれているため、オフライン保存は1つのタブのみで有効です。");
      } else if (err.code === 'unimplemented') {
        console.warn("現在のブラウザはオフライン保存をサポートしていません。");
      }
    });
  }
} catch (e) {
  console.error("Firebase初期化エラー:", e);
}

const STORAGE_KEY = 'slow_life_shopping_data_v2';
const AUTH_KEY = 'slow_life_auth_v2';
const SHARED_DOC_ID = 'company_8349'; // パスワードをクラウド上の部屋IDとして使用

const App: React.FC = () => {
  const initialState: AppState = {
    currentLocation: null,
    lists: {
      slowlife1: [],
      slowlife2: [],
    },
    masterHistory: [],
  };

  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    return localStorage.getItem(AUTH_KEY) === 'true';
  });

  const [state, setState] = useState<AppState>(initialState);
  const [isSyncing, setIsSyncing] = useState(false);

  // 1. クラウド(Firebase)から最新データを受け取る
  useEffect(() => {
    if (!db || !isLoggedIn) return;

    setIsSyncing(true);
    // Firestoreのドキュメントをリアルタイム監視
    const unsub = onSnapshot(doc(db, "shopping_lists", SHARED_DOC_ID), (docSnap) => {
      if (docSnap.exists()) {
        const cloudData = docSnap.data() as AppState;
        setState(prev => ({
          ...cloudData,
          currentLocation: prev.currentLocation // 拠点選択(1か2か)は各スマホで別々に保持
        }));
      } else {
        // クラウドにデータがない場合は初期状態を書き込む
        syncToCloud(initialState);
      }
      setIsSyncing(false);
    }, (error) => {
      console.error("同期エラー:", error);
      setIsSyncing(false);
    });

    return () => unsub();
  }, [isLoggedIn]);

  // 2. クラウドへデータを保存する関数
  const syncToCloud = async (newState: AppState) => {
    if (!db) {
      // Firebase未設定の場合は自分のスマホ内(Local)だけに保存
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
      return;
    }

    setIsSyncing(true);
    try {
      // currentLocationは同期対象外（人によって1を見てるか2を見てるか違うため）
      const { currentLocation, ...dataToSync } = newState;
      await setDoc(doc(db, "shopping_lists", SHARED_DOC_ID), dataToSync);
    } catch (e) {
      console.error("クラウド保存失敗:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem(AUTH_KEY, 'true');
  };

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation || !name.trim()) return prev;

      const newItem: ShoppingItem = {
        id: crypto.randomUUID(),
        name: name.trim(),
        completed: false,
        createdAt: Date.now(),
      };

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [newItem, ...prev.lists[currentLocation]],
        },
        masterHistory: Array.from(new Set([name.trim(), ...prev.masterHistory])),
      };

      syncToCloud(newState);
      return newState;
    });
  }, []);

  const toggleItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, completed: !item.completed } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const deleteItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].filter(item => item.id !== id),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const resetList = useCallback(() => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;
      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [],
        },
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const deleteHistoryItem = useCallback((name: string) => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: prev.masterHistory.filter(item => item !== name),
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const resetToPrototype1 = useCallback(() => {
    if (window.confirm("全てのデータを初期化しログアウトしますか？")) {
      localStorage.removeItem(STORAGE_KEY);
      localStorage.removeItem(AUTH_KEY);
      setIsLoggedIn(false);
      const newState = initialState;
      setState(newState);
      syncToCloud(newState);
    }
  }, [initialState]);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
        <LoginScreen onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
      {!state.currentLocation ? (
        <LocationSelector 
          onSelect={setLocation} 
          onResetApp={resetToPrototype1} 
        />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          isSyncing={isSyncing}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onDelete={deleteItem}
          onReset={resetList}
          onResetApp={resetToPrototype1}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { initializeApp } from 'https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js';
import { 
  getFirestore, 
  doc, 
  onSnapshot, 
  setDoc, 
  enableIndexedDbPersistence 
} from 'https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js';
import { LocationId, ShoppingItem, AppState } from './types';
import LocationSelector from './components/LocationSelector';
import ShoppingListView from './components/ShoppingListView';
import LoginScreen from './components/LoginScreen';

/**
 * 【Firebase設定の貼り付け手順】
 * Firebaseコンソールで取得した config の内容を下の {} 内に上書きしてください。
 */
const firebaseConfig = {
  apiKey: "ここに貼り付け",
  authDomain: "ここに貼り付け",
  projectId: "ここに貼り付け",
  storageBucket: "ここに貼り付け",
  messagingSenderId: "ここに貼り付け",
  appId: "ここに貼り付け"
};

// Firebaseの初期化
let db: any = null;
try {
  if (firebaseConfig.apiKey && firebaseConfig.apiKey !== "YOUR_API_KEY" && firebaseConfig.apiKey !== "ここに貼り付け") {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);

    enableIndexedDbPersistence(db).catch((err: any) => {
      if (err.code === 'failed-precondition') {
        console.warn("複数タブが開かれているため、オフライン保存は1つのタブのみで有効です。");
      } else if (err.code === 'unimplemented') {
        console.warn("現在のブラウザはオフライン保存をサポートしていません。");
      }
    });
  }
} catch (e) {
  console.error("Firebase初期化エラー:", e);
}

const STORAGE_KEY = 'slow_life_shopping_data_v2';
const AUTH_KEY = 'slow_life_auth_v2';
const SHARED_DOC_ID = 'company_8349';

const App: React.FC = () => {
  const initialState: AppState = {
    currentLocation: null,
    lists: {
      slowlife1: [],
      slowlife2: [],
    },
    masterHistory: [],
  };

  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    return localStorage.getItem(AUTH_KEY) === 'true';
  });

  const [state, setState] = useState<AppState>(initialState);
  const [isSyncing, setIsSyncing] = useState(false);

  // 1. クラウド(Firebase)から最新データを受け取る
  useEffect(() => {
    if (!db || !isLoggedIn) return;

    setIsSyncing(true);
    const unsub = onSnapshot(doc(db, "shopping_lists", SHARED_DOC_ID), (docSnap) => {
      if (docSnap.exists()) {
        const cloudData = docSnap.data() as AppState;
        setState(prev => ({
          ...cloudData,
          currentLocation: prev.currentLocation
        }));
      } else {
        // クラウドにデータがない（または削除された）場合は初期状態を書き込む
        syncToCloud(initialState);
      }
      setIsSyncing(false);
    }, (error) => {
      console.error("同期エラー:", error);
      setIsSyncing(false);
    });

    return () => unsub();
  }, [isLoggedIn]);

  // 2. クラウドへデータを保存する関数
  const syncToCloud = async (newState: AppState) => {
    if (!db) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
      return;
    }

    setIsSyncing(true);
    try {
      const { currentLocation, ...dataToSync } = newState;
      await setDoc(doc(db, "shopping_lists", SHARED_DOC_ID), dataToSync);
    } catch (e) {
      console.error("クラウド保存失敗:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem(AUTH_KEY, 'true');
  };

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation || !name.trim()) return prev;

      const newItem: ShoppingItem = {
        id: crypto.randomUUID(),
        name: name.trim(),
        completed: false,
        createdAt: Date.now(),
      };

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [newItem, ...prev.lists[currentLocation]],
        },
        masterHistory: Array.from(new Set([name.trim(), ...prev.masterHistory])),
      };

      syncToCloud(newState);
      return newState;
    });
  }, []);

  const toggleItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, completed: !item.completed } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const deleteItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].filter(item => item.id !== id),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const resetList = useCallback(() => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;
      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [],
        },
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const resetHistory = useCallback(() => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: [],
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const deleteHistoryItem = useCallback((name: string) => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: prev.masterHistory.filter(item => item !== name),
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  // 全初期化（クラウド上のデータも消去してログアウト）
  const resetToPrototype1 = useCallback(async () => {
    // 1. クラウドを初期化
    await syncToCloud(initialState);
    // 2. ローカルストレージを削除
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(AUTH_KEY);
    // 3. アプリの状態を戻す
    setState(initialState);
    setIsLoggedIn(false);
  }, [initialState]);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
        <LoginScreen onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
      {!state.currentLocation ? (
        <LocationSelector 
          onSelect={setLocation} 
          onResetApp={resetToPrototype1} 
        />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          isSyncing={isSyncing}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onDelete={deleteItem}
          onReset={resetList}
          onResetHistory={resetHistory}
          onResetApp={resetToPrototype1}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ShoppingItem, LocationId } from '../types';
import MasterListModal from './MasterListModal';

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: string[];
  isSyncing?: boolean;
  onBack: () => void;
  onAdd: (name: string) => void;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onReset: () => void;
  onResetHistory: () => void;
  onResetApp: () => void;
  onDeleteHistoryItem: (name: string) => void;
}

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  isSyncing = false,
  onBack,
  onAdd,
  onToggle,
  onDelete,
  onReset,
  onResetHistory,
  onResetApp,
  onDeleteHistoryItem,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [confirmType, setConfirmType] = useState<'list' | 'history' | 'app' | null>(null);
  const [password, setPassword] = useState('');
  const [passError, setPassError] = useState(false);

  const recognitionRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.lang = 'ja-JP';
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputValue(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, []);

  const handleVoiceInput = () => {
    if (!recognitionRef.current) {
      alert('音声入力に対応していません');
      return;
    }
    if (isListening) {
      recognitionRef.current.stop();
    } else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleAdd = () => {
    if (inputValue.trim()) {
      onAdd(inputValue);
      setInputValue('');
    }
  };

  const handleAppReset = () => {
    if (password === 'hirake5ma') {
      onResetApp();
      setConfirmType(null);
      setPassword('');
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  };

  return (
    <div className="flex flex-col h-full overflow-hidden relative">
      {/* Header */}
      <header className="px-4 pt-6 pb-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <div className="flex items-center">
          <button onClick={onBack} className="text-gray-400 hover:text-gray-600 p-2">
            <i className="fa-solid fa-chevron-left text-xl"></i>
          </button>
          {isSyncing && (
            <div className="ml-1 text-blue-400 animate-pulse">
              <i className="fa-solid fa-cloud text-[10px]"></i>
            </div>
          )}
        </div>

        <div className="flex flex-col items-center">
          <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        </div>

        <div className="flex items-center gap-1">
          <button 
            onClick={() => setConfirmType('list')}
            className="text-red-400 hover:text-red-600 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-red-50 transition-all border border-transparent active:border-red-100"
          >
            リスト消去
          </button>

          <div className="relative">
            <button 
              onClick={() => setShowSettings(!showSettings)} 
              className="text-gray-300 hover:text-gray-500 p-2"
            >
              <i className="fa-solid fa-ellipsis-vertical text-lg"></i>
            </button>

            {showSettings && (
              <div className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-xl border border-gray-100 py-2 z-50 animate-fadeIn overflow-hidden">
                <button 
                  onClick={() => { setConfirmType('history'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-gray-500 hover:bg-gray-50 flex items-center gap-3"
                >
                  <i className="fa-solid fa-clock-rotate-left w-4 text-center"></i>
                  履歴リストを空にする
                </button>
                <div className="border-t border-gray-50"></div>
                <button 
                  onClick={() => { setConfirmType('app'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-red-400 hover:bg-red-50 flex items-center gap-3 font-bold"
                >
                  <i className="fa-solid fa-rotate-left w-4 text-center"></i>
                  全初期化 (管理者用)
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Input Area */}
      <div className="p-6 bg-white shadow-sm space-y-4">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
              placeholder="何を買いますか？"
              className="w-full pl-4 pr-10 py-3 rounded-2xl border-2 border-gray-100 focus:border-gray-200 outline-none transition-all"
            />
            <button
              onClick={handleVoiceInput}
              className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-full transition-colors ${
                isListening ? 'text-red-500 animate-pulse bg-red-50' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              <i className="fa-solid fa-microphone"></i>
            </button>
          </div>
          <button
            onClick={handleAdd}
            style={{ backgroundColor: themeColor }}
            className="w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg active:scale-90 transition-transform"
          >
            <i className="fa-solid fa-plus text-xl"></i>
          </button>
        </div>

        <button
          onClick={() => setShowHistory(true)}
          className="w-full py-2.5 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200 hover:bg-[#e9e5e0] transition-colors"
        >
          <i className="fa-solid fa-list-ul"></i>
          履歴リストから選ぶ
        </button>
      </div>

      {/* List Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-300">
            <i className="fa-solid fa-basket-shopping text-4xl mb-4 opacity-30"></i>
            <p className="text-sm font-bold opacity-50">買い物依頼はありません</p>
          </div>
        ) : (
          items.map((item) => (
            <div
              key={item.id}
              className={`flex items-center gap-3 p-4 bg-white rounded-2xl shadow-sm border border-gray-100 animate-fadeIn ${
                item.completed ? 'opacity-60 bg-gray-50' : ''
              }`}
            >
              <button
                onClick={() => onToggle(item.id)}
                className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                  item.completed 
                    ? 'bg-green-500 border-green-500 text-white' 
                    : 'border-gray-200 text-transparent'
                }`}
              >
                <i className="fa-solid fa-check text-xs"></i>
              </button>
              <div className="flex-1 flex items-baseline justify-between gap-2">
                <span 
                  className={`text-[15px] font-bold transition-all ${
                    item.completed ? 'line-through text-gray-400 font-normal' : 'text-[#4a3f35]'
                  }`}
                >
                  {item.name}
                </span>
                <span className="text-[10px] text-gray-500 font-normal shrink-0">
                  {formatDate(item.createdAt)}
                </span>
              </div>
              <button
                onClick={() => onDelete(item.id)}
                className="text-gray-200 hover:text-red-400 p-2 transition-colors"
              >
                <i className="fa-solid fa-trash-can text-sm"></i>
              </button>
            </div>
          ))
        )}
      </div>

      {/* Confirmation Dialogs */}
      {confirmType && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-fadeIn">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { setConfirmType(null); setPassword(''); setPassError(false); }} />
          <div className="relative bg-white w-full max-w-xs rounded-[32px] p-8 shadow-2xl text-center space-y-6">
            <div className={`w-14 h-14 rounded-full flex items-center justify-center mx-auto ${
              confirmType === 'list' || confirmType === 'history' ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-500'
            }`}>
              <i className={`fa-solid ${confirmType === 'app' ? 'fa-lock' : 'fa-trash-can'} text-xl`}></i>
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-800 mb-2">
                {confirmType === 'list' ? '現在のリストを空にしますか？' : 
                 confirmType === 'history' ? '履歴をすべて消去しますか？' : 
                 '全初期化を実行しますか？'}
              </h3>
              <p className="text-xs text-gray-500 leading-relaxed mb-4">
                {confirmType === 'list' ? `${locationName} の依頼リストをクリアします。` :
                 confirmType === 'history' ? '過去に登録した履歴データをすべてクリアします。' :
                 'クラウド上のデータも含めすべてリセットし、ログアウトします。パスワードが必要です。'}
              </p>

              {confirmType === 'app' && (
                <>
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => { setPassword(e.target.value); setPassError(false); }}
                    placeholder="パスワード"
                    className={`w-full px-4 py-3 rounded-xl border-2 outline-none transition-all text-center ${
                      passError ? 'border-red-300 bg-red-50' : 'border-gray-100 focus:border-gray-300'
                    }`}
                  />
                  {passError && <p className="text-[10px] text-red-500 mt-2 font-bold">パスワードが違います</p>}
                </>
              )}
            </div>
            <div className="flex flex-col gap-2">
              <button
                onClick={() => {
                  if (confirmType === 'list') {
                    onReset();
                    setConfirmType(null);
                  } else if (confirmType === 'history') {
                    onResetHistory();
                    setConfirmType(null);
                  } else {
                    handleAppReset();
                  }
                }}
                className={`w-full py-4 rounded-2xl font-bold text-sm text-white active:scale-95 transition-all ${
                  confirmType === 'app' ? 'bg-gray-800' : 'bg-red-500 shadow-lg shadow-red-100'
                }`}
              >
                {confirmType === 'app' ? '実行する' : 'はい、消去する'}
              </button>
              <button
                onClick={() => { setConfirmType(null); setPassword(''); setPassError(false); }}
                className="w-full py-3 bg-transparent text-gray-400 rounded-2xl font-bold text-sm active:scale-95 transition-all"
              >
                キャンセル
              </button>
            </div>
          </div>
        </div>
      )}

      {/* History Modal */}
      {showHistory && (
        <MasterListModal
          history={masterHistory}
          onSelect={(name) => {
            onAdd(name);
            setShowHistory(false);
          }}
          onDeleteHistoryItem={onDeleteHistoryItem}
          onClose={() => setShowHistory(false)}
          themeColor={themeColor}
        />
      )}

