import React, { useRef, useEffect } from 'react';
import Sortable from 'https://esm.sh/sortablejs@1.15.2';
import { HistoryItem } from '../types';

interface Props {
  history: HistoryItem[];
  onSelect: (name: string, color: string) => void;
  onDeleteHistoryItem: (name: string) => void;
  onUpdateHistoryOrder: (history: HistoryItem[]) => void;
  onClose: () => void;
  themeColor: string;
}

const MasterListModal: React.FC<Props> = ({ history, onSelect, onDeleteHistoryItem, onUpdateHistoryOrder, onClose, themeColor }) => {
  const gridRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);

  useEffect(() => {
    if (gridRef.current && history.length > 0) {
      sortableRef.current = new Sortable(gridRef.current, {
        animation: 150,
        ghostClass: 'opacity-20',
        delay: 100,
        delayOnTouchOnly: true,
        onEnd: (evt: any) => {
          const newHistory = [...history];
          const [movedItem] = newHistory.splice(evt.oldIndex, 1);
          newHistory.splice(evt.newIndex, 0, movedItem);
          onUpdateHistoryOrder(newHistory);
        },
      });
    }
    return () => {
      if (sortableRef.current) {
        sortableRef.current.destroy();
        sortableRef.current = null;
      }
    };
  }, [history, onUpdateHistoryOrder]);

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center animate-fadeIn">
      <div 
        className="absolute inset-0 bg-black/40 backdrop-blur-sm" 
        onClick={onClose}
      />

      <div className="relative bg-white w-full max-w-md h-[70vh] rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-slideUp">
        <div className="px-6 py-4 border-b flex items-center justify-between sticky top-0 bg-white z-10">
          <h3 className="text-lg font-bold">過去の履歴から追加</h3>
          <button onClick={onClose} className="w-8 h-8 rounded-full bg-gray-100 text-gray-400 flex items-center justify-center active:scale-90 transition-transform">
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          {history.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 py-12">
              <i className="fa-solid fa-clock-rotate-left text-4xl mb-4 opacity-20"></i>
              <p>履歴はまだありません</p>
            </div>
          ) : (
            <div ref={gridRef} className="grid grid-cols-2 gap-3 pb-8">
              {history.map((item, index) => (
                <div
                  key={`${item.name}-${index}`}
                  className="relative group animate-fadeIn cursor-grab active:cursor-grabbing"
                >
                  <button
                    onClick={() => onSelect(item.name, item.color)}
                    className="w-full p-4 pr-10 text-left border border-gray-100 rounded-2xl hover:border-gray-200 active:scale-[0.98] transition-all flex items-center shadow-sm"
                    style={{ backgroundColor: item.color || '#fdfaf6' }}
                  >
                    <span className="text-sm font-bold text-[#6b5e51] line-clamp-2">
                      {item.name}
                    </span>
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      onDeleteHistoryItem(item.name);
                    }}
                    className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center text-gray-300 hover:text-red-400 transition-colors rounded-full hover:bg-red-50/50"
                  >
                    <i className="fa-solid fa-trash-can text-[10px]"></i>
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="p-6 border-t bg-gray-50 text-center text-xs text-gray-400">
          カードをドラッグして順番を入れ替えられます
        </div>
      </div>
    </div>
  );
};

