              </div>
              <button onClick={(e) => { e.stopPropagation(); onDelete(item.id); }} className="text-gray-300 hover:text-red-400 p-2 transition-colors shrink-0">
                <i className="fa-solid fa-trash-can text-sm"></i>
              </button>
            </div>
