          >
            カゴ消去
          </button>
          <div className="relative">
            <button onClick={(e) => { e.stopPropagation(); setShowSettings(!showSettings); }} className="text-gray-300 hover:text-gray-500 p-2">
              <i className="fa-solid fa-ellipsis-vertical text-lg"></i>
