import React, { useState, useEffect, useCallback } from 'react';
import { initializeApp } from 'firebase/app';
import { 
  getFirestore, 
  doc, 
  onSnapshot, 
  setDoc, 
  enableIndexedDbPersistence 
} from 'firebase/firestore';
import { LocationId, ShoppingItem, AppState, HistoryItem } from './types';
import LocationSelector from './components/LocationSelector';
import ShoppingListView from './components/ShoppingListView';
import LoginScreen from './components/LoginScreen';

/**
 * 【Firebase設定の貼り付け手順】
 * Firebaseコンソールで取得した config の内容を下の {} 内に上書きしてください。
 */
const firebaseConfig = {
  apiKey: "ここに貼り付け",
  authDomain: "ここに貼り付け",
  projectId: "ここに貼り付け",
  storageBucket: "ここに貼り付け",
  messagingSenderId: "ここに貼り付け",
  appId: "ここに貼り付け"
};

// Firebaseの初期化
let db: any = null;
try {
  if (firebaseConfig.apiKey && firebaseConfig.apiKey !== "ここに貼り付け") {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);

    enableIndexedDbPersistence(db).catch((err: any) => {
      if (err.code === 'failed-precondition') {
        console.warn("複数タブが開かれているため、オフライン保存は1つのタブのみで有効です。");
      } else if (err.code === 'unimplemented') {
        console.warn("現在のブラウザはオフライン保存をサポートしていません。");
      }
    });
  }
} catch (e) {
  console.error("Firebase初期化エラー:", e);
}

const STORAGE_KEY = 'slow_life_shopping_data_v2';
const AUTH_KEY = 'slow_life_auth_v2';
const SHARED_DOC_ID = 'company_8349';

// 【プロトタイプ１】としての初期状態定義
const PROTOTYPE_1_STATE: AppState = {
  currentLocation: null,
  lists: {
    slowlife1: [],
    slowlife2: [],
  },
  masterHistory: [],
};

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    return localStorage.getItem(AUTH_KEY) === 'true';
  });

  const [state, setState] = useState<AppState>(PROTOTYPE_1_STATE);
  const [isSyncing, setIsSyncing] = useState(false);

  // クラウドへデータを保存する関数
  const syncToCloud = async (newState: AppState) => {
    if (!db) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
      return;
    }

    setIsSyncing(true);
    try {
      const { currentLocation, ...dataToSync } = newState;
      await setDoc(doc(db, "shopping_lists", SHARED_DOC_ID), dataToSync);
    } catch (e) {
      console.error("クラウド保存失敗:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  // クラウドから最新データを受け取る
  useEffect(() => {
    if (!db || !isLoggedIn) return;

    setIsSyncing(true);
    const unsub = onSnapshot(doc(db, "shopping_lists", SHARED_DOC_ID), (docSnap) => {
      if (docSnap.exists()) {
        const cloudData = docSnap.data() as any;

        const sanitizedHistory = (cloudData.masterHistory || []).map((h: any) => 
          typeof h === 'string' ? { name: h, color: '#ffffff' } : h
        );

        setState(prev => ({
          ...cloudData,
          masterHistory: sanitizedHistory,
          currentLocation: prev.currentLocation
        }));
      } else {
        syncToCloud(PROTOTYPE_1_STATE);
      }
      setIsSyncing(false);
    }, (error) => {
      console.error("同期エラー:", error);
      setIsSyncing(false);
    });

    return () => unsub();
  }, [isLoggedIn]);

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem(AUTH_KEY, 'true');
  };

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string, color: string = '#ffffff', quantity: string = '') => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation || !name.trim()) return prev;

      const trimmedName = name.trim();
      const newItem: ShoppingItem = {
        id: crypto.randomUUID(),
        name: trimmedName,
        completed: false,
        createdAt: Date.now(),
        color: color,
        quantity: quantity,
      };

      const newHistory: HistoryItem[] = [
        { name: trimmedName, color },
        ...prev.masterHistory.filter(h => h.name !== trimmedName)
      ].slice(0, 100);

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [newItem, ...prev.lists[currentLocation]],
        },
        masterHistory: newHistory,
      };

      syncToCloud(newState);
      return newState;
    });
  }, []);

  const toggleItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, completed: !item.completed } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const updateItemColor = (id: string, color: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, color } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const updateItemQuantity = (id: string, quantity: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, quantity } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const deleteItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].filter(item => item.id !== id),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const updateListOrder = useCallback((items: ShoppingItem[]) => {
    setState(prev => {
      if (!prev.currentLocation) return prev;
      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [prev.currentLocation]: items,
        },
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const updateHistoryOrder = useCallback((newHistory: HistoryItem[]) => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: newHistory,
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const resetList = useCallback(() => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;
      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [],
        },
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  // 履歴リストをすべて削除する関数
  const resetHistory = useCallback(() => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: [], // 履歴を完全に空にする
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const deleteHistoryItem = useCallback((name: string) => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: prev.masterHistory.filter(h => h.name !== name),
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  // アプリを【プロトタイプ１】の初期状態に戻す関数
  const resetToPrototype1 = useCallback(async () => {
    await syncToCloud(PROTOTYPE_1_STATE);
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(AUTH_KEY);
    setState(PROTOTYPE_1_STATE);
    setIsLoggedIn(false);
  }, []);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
        <LoginScreen onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
      {!state.currentLocation ? (
        <LocationSelector 
          onSelect={setLocation} 
          onResetApp={resetToPrototype1} 
        />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          isSyncing={isSyncing}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onUpdateColor={updateItemColor}
          onUpdateQuantity={updateItemQuantity}
          onDelete={deleteItem}
          onUpdateOrder={updateListOrder}
          onUpdateHistoryOrder={updateHistoryOrder}
          onReset={resetList}
          onResetHistory={resetHistory}
          onResetApp={resetToPrototype1}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import Sortable from 'sortablejs';
import { ShoppingItem, LocationId, HistoryItem } from '../types';
import MasterListModal from './MasterListModal';
import { GoogleGenAI, Type } from "@google/genai";

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: HistoryItem[];
  isSyncing?: boolean;
  onBack: () => void;
  onAdd: (name: string, color?: string, quantity?: string) => void;
  onToggle: (id: string) => void;
  onUpdateColor: (id: string, color: string) => void;
  onUpdateQuantity: (id: string, quantity: string) => void;
  onDelete: (id: string) => void;
  onUpdateOrder: (items: ShoppingItem[]) => void;
  onUpdateHistoryOrder: (history: HistoryItem[]) => void;
  onReset: () => void;
  onResetHistory: () => void;
  onResetApp: () => void;
  onDeleteHistoryItem: (name: string) => void;
}

const COLORS = [
  { id: 'white', value: '#ffffff', label: '標準' },
  { id: 'pink', value: '#ffecf0', label: 'さくら' },
  { id: 'blue', value: '#e3f2fd', label: 'そら' },
  { id: 'green', value: '#f1f8e9', label: 'わかば' },
];

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  isSyncing = false,
  onBack,
  onAdd,
  onToggle,
  onUpdateColor,
  onUpdateQuantity,
  onDelete,
  onUpdateOrder,
  onUpdateHistoryOrder,
  onReset,
  onResetHistory,
  onResetApp,
  onDeleteHistoryItem,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [quantityValue, setQuantityValue] = useState('');
  const [selectedColor, setSelectedColor] = useState('#ffffff');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [confirmType, setConfirmType] = useState<'list' | 'history' | 'app' | null>(null);
  const [password, setPassword] = useState('');
  const [passError, setPassError] = useState(false);

  // AI Mode States
  const [aiMode, setAiMode] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<{ name: string; quantity: string; selected: boolean }[]>([]);
  const [aiSelectedColor, setAiSelectedColor] = useState('#ffffff');

  // Item Edit States
  const [editingColorId, setEditingColorId] = useState<string | null>(null);
  const [editingQuantityId, setEditingQuantityId] = useState<string | null>(null);
  const [tempQuantity, setTempQuantity] = useState('');

  const recognitionRef = useRef<any>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    if (listRef.current && items.length > 0) {
      sortableRef.current = new Sortable(listRef.current, {
        animation: 150,
        ghostClass: 'opacity-20',
        delay: 100,
        delayOnTouchOnly: true,
        onEnd: (evt: any) => {
          const newItems = [...items];
          const [movedItem] = newItems.splice(evt.oldIndex, 1);
          newItems.splice(evt.newIndex, 0, movedItem);
          onUpdateOrder(newItems);
        },
      });
    }
    return () => {
      if (sortableRef.current) {
        sortableRef.current.destroy();
        sortableRef.current = null;
      }
    };
  }, [items, onUpdateOrder]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.lang = 'ja-JP';
      recognition.interimResults = false;

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onerror = () => setIsListening(false);

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputValue(transcript);
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, []);

  const handleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!recognitionRef.current) {
      alert('音声入力に対応していません');
      return;
    }

    if (isListening) {
      try {
        recognitionRef.current.stop();
      } catch (err) {
        console.error("Speech stop error:", err);
      }
    } else {
      try {
        recognitionRef.current.start();
      } catch (err) {
        console.error("Speech start error:", err);
        setIsListening(false);
      }
    }
  };

  const handleAiAction = async () => {
    if (!inputValue.trim()) return;

    setIsAiLoading(true);
    setAiSuggestions([]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `料理名「${inputValue}」を作るために、一般的なスーパーで購入が必要な食材リストを教えてください。`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              ingredients: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING, description: '食材名' },
                    quantity: { type: Type.STRING, description: '目安の分量' }
                  },
                  required: ['name', 'quantity']
                }
              }
            },
            required: ['ingredients']
          }
        }
      });

      const data = JSON.parse(response.text || '{"ingredients":[]}');
      setAiSuggestions(data.ingredients.map((ing: any) => ({ ...ing, selected: true })));
    } catch (e) {
      console.error("AI予測失敗:", e);
      alert("食材の予測に失敗しました。時間をおいて再度お試しください。");
    } finally {
      setIsAiLoading(false);
    }
  };

  const updateAiSuggestionQuantity = (index: number, newQty: string) => {
    const newSuggestions = [...aiSuggestions];
    newSuggestions[index].quantity = newQty;
    setAiSuggestions(newSuggestions);
  };

  const addSelectedAiItems = () => {
    const selectedItems = aiSuggestions.filter(s => s.selected);
    selectedItems.forEach(item => {
      onAdd(item.name, aiSelectedColor, item.quantity);
    });
    setAiSuggestions([]);
    setInputValue('');
    setAiMode(false);
  };

  const handleAdd = () => {
    if (aiMode) {
      handleAiAction();
      return;
    }
    if (inputValue.trim()) {
      onAdd(inputValue, selectedColor, quantityValue.trim());
      setInputValue('');
      setQuantityValue('');
      setSelectedColor('#ffffff');
    }
  };

  const handleAppReset = () => {
    if (password === 'hirake5ma') {
      onResetApp();
      setConfirmType(null);
      setPassword('');
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  };

  const saveQuantityEdit = (id: string) => {
    onUpdateQuantity(id, tempQuantity);
    setEditingQuantityId(null);
    setTempQuantity('');
  };

  return (
    <div className="flex flex-col h-full overflow-hidden relative" onClick={() => { setEditingColorId(null); setEditingQuantityId(null); }}>
      <header className="px-4 pt-6 pb-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <div className="flex items-center">
          <button onClick={onBack} className="text-gray-400 hover:text-gray-600 p-2">
            <i className="fa-solid fa-chevron-left text-xl"></i>
          </button>
          {isSyncing && (
            <div className="ml-1 text-blue-400 animate-pulse">
              <i className="fa-solid fa-cloud text-[10px]"></i>
            </div>
          )}
        </div>
        <div className="flex flex-col items-center">
          <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        </div>
        <div className="flex items-center gap-1">
          <button 
            onClick={(e) => { e.stopPropagation(); setConfirmType('list'); }}
            className="text-red-400 hover:text-red-600 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-red-50 transition-all border border-transparent active:border-red-100"
          >
            カゴ消去
          </button>
          <div className="relative">
            <button onClick={(e) => { e.stopPropagation(); setShowSettings(!showSettings); }} className="text-gray-300 hover:text-gray-500 p-2">
              <i className="fa-solid fa-ellipsis-vertical text-lg"></i>
            </button>
            {showSettings && (
              <div className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-xl border border-gray-100 py-2 z-50 animate-fadeIn overflow-hidden">
                <button 
                  onClick={() => { setConfirmType('history'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-gray-500 hover:bg-gray-50 flex items-center gap-3"
                >
                  <i className="fa-solid fa-clock-rotate-left w-4 text-center"></i>
                  履歴リストを空にする
                </button>
                <div className="border-t border-gray-50"></div>
                <button 
                  onClick={() => { setConfirmType('app'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-red-400 hover:bg-red-50 flex items-center gap-3 font-bold"
                >
                  <i className="fa-solid fa-rotate-left w-4 text-center"></i>
                  全初期化 (プロトタイプ1)
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="p-6 bg-white shadow-sm space-y-4" onClick={(e) => e.stopPropagation()}>
        <div className="flex flex-col gap-3">
          <div className="flex items-center justify-between px-1">
            <div className="flex gap-4">
              {COLORS.map((color) => (
                <button
                  key={color.id}
                  onClick={() => setSelectedColor(color.value)}
                  className={`w-7 h-7 rounded-full border-2 transition-all shadow-sm flex items-center justify-center ${
                    selectedColor === color.value ? 'scale-110 border-gray-400' : 'border-transparent'
                  }`}
                  style={{ backgroundColor: color.value }}
                >
                  {selectedColor === color.value && <i className="fa-solid fa-check text-[10px] text-gray-400"></i>}
                </button>
              ))}
            </div>
            <button 
              onClick={() => {
                setAiMode(!aiMode);
                setAiSuggestions([]);
                setInputValue('');
              }}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[11px] font-bold transition-all border-2 ${
                aiMode ? 'bg-purple-500 border-purple-500 text-white shadow-md' : 'bg-white border-gray-100 text-gray-400'
              }`}
            >
              <i className={`fa-solid fa-wand-magic-sparkles ${aiMode ? 'animate-pulse' : ''}`}></i>
              {aiMode ? 'AIモードON' : 'AIモード'}
            </button>
          </div>

          <div className="space-y-2">
            <div className="relative flex items-center gap-2">
              <div className="relative flex-1">
                <input
                  type="text"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  placeholder={aiMode ? "作りたいメニューと何人前か入力" : "何を買いますか？"}
                  className={`w-full pl-4 pr-10 py-3 rounded-2xl border-2 outline-none transition-all ${
                    aiMode ? 'border-purple-100 focus:border-purple-300 bg-purple-50/20' : 'border-gray-100 focus:border-gray-200'
                  }`}
                />
                <button
                  onClick={handleVoiceInput}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-full transition-colors z-10 ${
                    isListening 
                      ? 'text-red-500 animate-pulse bg-red-50' 
                      : (aiMode ? 'text-purple-400 hover:text-purple-600' : 'text-gray-400 hover:text-gray-600')
                  }`}
                >
                  <i className="fa-solid fa-microphone"></i>
                </button>
              </div>
              <button
                onClick={handleAdd}
                disabled={isAiLoading}
                style={{ backgroundColor: aiMode ? '#a855f7' : themeColor }}
                className="w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg active:scale-90 transition-all shrink-0 disabled:opacity-50"
              >
                {isAiLoading ? (
                  <i className="fa-solid fa-circle-notch animate-spin text-xl"></i>
                ) : (
                  <i className={`fa-solid ${aiMode ? 'fa-magnifying-glass' : 'fa-plus'} text-xl`}></i>
                )}
              </button>
            </div>

            {!aiMode && (
              <div className="w-full">
                <input
                  type="text"
                  value={quantityValue}
                  onChange={(e) => setQuantityValue(e.target.value)}
                  placeholder="個数を入力（任意）"
                  className="w-full px-4 py-2.5 rounded-xl border-2 border-gray-50 focus:border-gray-100 bg-gray-50/30 outline-none transition-all text-sm"
                />
              </div>
            )}

            {/* AI Suggestions Panel */}
            {aiSuggestions.length > 0 && (
              <div className="bg-purple-50/50 rounded-2xl p-4 border border-purple-100 animate-fadeIn space-y-3 shadow-sm">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[11px] font-bold text-purple-600 tracking-wider">予測食材（個数編集可）</span>
                  <button onClick={() => setAiSuggestions([])} className="text-purple-300 hover:text-purple-500">
                    <i className="fa-solid fa-xmark"></i>
                  </button>
                </div>
                <div className="grid grid-cols-1 gap-2 max-h-48 overflow-y-auto pr-1">
                  {aiSuggestions.map((s, idx) => (
                    <div 
                      key={idx} 
                      className={`flex items-center gap-2 p-2 rounded-xl border transition-all ${
                        s.selected ? 'bg-white border-purple-200 shadow-sm' : 'bg-transparent border-transparent opacity-40'
                      }`}
                    >
                      <button
                        onClick={() => {
                          const newS = [...aiSuggestions];
                          newS[idx].selected = !newS[idx].selected;
                          setAiSuggestions(newS);
                        }}
                        className={`w-6 h-6 rounded-md border flex items-center justify-center transition-all shrink-0 ${
                          s.selected ? 'bg-purple-500 border-purple-500 text-white' : 'border-purple-200'
                        }`}
                      >
                        {s.selected && <i className="fa-solid fa-check text-[10px]"></i>}
                      </button>
                      <div className="flex-1 min-w-0">
                        <span className="text-sm font-bold text-gray-700 truncate block">{s.name}</span>
                      </div>
                      <input
                        type="text"
                        value={s.quantity}
                        onChange={(e) => updateAiSuggestionQuantity(idx, e.target.value)}
                        className="w-20 px-2 py-1 text-xs border rounded-lg outline-none focus:border-purple-300 text-right bg-purple-50/30 font-bold text-purple-600"
                        placeholder="分量"
                      />
                    </div>
                  ))}
                </div>

                <div className="pt-2 space-y-3">
                  <div className="flex items-center justify-center gap-3 bg-white/50 py-2 rounded-xl border border-purple-100">
                    <span className="text-[10px] font-bold text-gray-400">カードの色:</span>
                    {COLORS.map((color) => (
                      <button
                        key={color.id}
                        onClick={() => setAiSelectedColor(color.value)}
                        className={`w-6 h-6 rounded-full border-2 transition-all ${
                          aiSelectedColor === color.value ? 'scale-110 border-purple-400' : 'border-transparent'
                        }`}
                        style={{ backgroundColor: color.value }}
                      />
                    ))}
                  </div>
                  <button
                    onClick={addSelectedAiItems}
                    className="w-full py-3 bg-purple-600 text-white rounded-xl text-sm font-bold shadow-md active:scale-95 transition-all"
                  >
                    選択した食材を追加
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
        <button
          onClick={() => setShowHistory(true)}
          className="w-full py-2.5 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200 hover:bg-[#e9e5e0] transition-colors"
        >
          <i className="fa-solid fa-list-ul"></i>
          履歴リストから選ぶ
        </button>
      </div>

      <div ref={listRef} className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-300 pointer-events-none">
            <i className="fa-solid fa-basket-shopping text-4xl mb-4 opacity-30"></i>
            <p className="text-sm font-bold opacity-50">買い物依頼はありません</p>
          </div>
        ) : (
          items.map((item) => (
            <div
              key={item.id}
              className={`flex items-center gap-3 p-4 rounded-2xl shadow-sm border border-gray-100 cursor-grab active:cursor-grabbing relative ${
                item.completed ? 'opacity-60 grayscale-[0.5]' : ''
              }`}
              style={{ backgroundColor: item.color || '#ffffff' }}
            >
              <button
                onClick={(e) => { e.stopPropagation(); onToggle(item.id); }}
                className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all bg-white shrink-0 ${
                  item.completed ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200 text-transparent'
                }`}
              >
                <i className="fa-solid fa-check text-xs"></i>
              </button>
              <div className="flex-1 flex items-baseline justify-between gap-2 overflow-hidden">
                {editingQuantityId === item.id ? (
                  <div className="flex-1 flex gap-2 items-center" onClick={(e) => e.stopPropagation()}>
                    <input
                      autoFocus
                      type="text"
                      value={tempQuantity}
                      onChange={(e) => setTempQuantity(e.target.value)}
                      onBlur={() => saveQuantityEdit(item.id)}
                      onKeyDown={(e) => e.key === 'Enter' && saveQuantityEdit(item.id)}
                      className="w-full px-2 py-1 text-sm border-2 border-gray-200 rounded-lg outline-none focus:border-gray-400 bg-white font-bold"
                    />
                  </div>
                ) : (
                  <>
                    <span className={`text-[15px] font-bold transition-all truncate ${item.completed ? 'line-through text-gray-400 font-normal' : 'text-[#4a3f35]'}`}>
                      {item.name}
                      {item.quantity && (
                        <span className="ml-2 px-2 py-0.5 bg-white/50 rounded-lg text-xs font-bold text-gray-500">
                          {item.quantity}
                        </span>
                      )}
                    </span>
                    <span className="text-[10px] text-gray-500 font-normal shrink-0">{formatDate(item.createdAt)}</span>
                  </>
                )}
              </div>

              <div className="flex items-center gap-1 shrink-0">
                {/* Quantity edit button */}
                <button 
                  onClick={(e) => { e.stopPropagation(); setEditingQuantityId(item.id); setTempQuantity(item.quantity || ''); }}
                  className="text-gray-300 hover:text-gray-500 p-2 transition-colors"
                >
                  <i className="fa-solid fa-pen-to-square text-sm"></i>
                </button>

                {/* Color Picker Toggle */}
                <div className="relative">
                  <button 
                    onClick={(e) => { e.stopPropagation(); setEditingColorId(editingColorId === item.id ? null : item.id); }}
                    className="text-gray-300 hover:text-gray-500 p-2 transition-colors"
                  >
                    <i className="fa-solid fa-palette text-sm"></i>
                  </button>
                  {editingColorId === item.id && (
                    <div className="absolute right-0 bottom-full mb-2 bg-white p-2 rounded-xl shadow-xl border border-gray-100 flex gap-2 z-20 animate-fadeIn" onClick={(e) => e.stopPropagation()}>
                      {COLORS.map((c) => (
                        <button
                          key={c.id}
                          onClick={() => { onUpdateColor(item.id, c.value); setEditingColorId(null); }}
                          className={`w-6 h-6 rounded-full border border-gray-100 shadow-sm ${item.color === c.value ? 'ring-2 ring-gray-400' : ''}`}
                          style={{ backgroundColor: c.value }}
                        />
                      ))}
                    </div>
                  )}
                </div>

                <button onClick={(e) => { e.stopPropagation(); onDelete(item.id); }} className="text-gray-300 hover:text-red-400 p-2 transition-colors shrink-0">
                  <i className="fa-solid fa-trash-can text-sm"></i>
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {confirmType && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-fadeIn">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { setConfirmType(null); setPassword(''); setPassError(false); }} />
          <div className="relative bg-white w-full max-w-xs rounded-[32px] p-8 shadow-2xl text-center space-y-6">
            <div className={`w-14 h-14 rounded-full flex items-center justify-center mx-auto ${confirmType === 'app' ? 'bg-gray-100' : 'bg-red-50 text-red-500'}`}>
              <i className={`fa-solid ${confirmType === 'app' ? 'fa-lock' : 'fa-trash-can'} text-xl`}></i>
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-800 mb-2">
                {confirmType === 'list' ? '現在のカゴを空にしますか？' : confirmType === 'history' ? '過去の履歴をすべて消去しますか？' : 'プロトタイプ１に戻しますか？'}
              </h3>
              {confirmType === 'app' && (
                <>
                  <p className="text-[10px] text-gray-400 mb-4">初期状態（データなし）にリセットされます</p>
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => { setPassword(e.target.value); setPassError(false); }}
                    placeholder="パスワードを入力"
                    className={`w-full px-4 py-3 rounded-xl border-2 outline-none transition-all text-center ${passError ? 'border-red-300 bg-red-50' : 'border-gray-100 focus:border-gray-300'}`}
                  />
                  {passError && <p className="text-center text-[10px] text-red-500 mt-2 font-bold">パスワードが違います</p>}
                </>
              )}
            </div>
            <div className="flex flex-col gap-2">
              <button
                onClick={() => {
                  if (confirmType === 'list') onReset();
                  else if (confirmType === 'history') onResetHistory();
                  else if (confirmType === 'app') { handleAppReset(); return; }
                  setConfirmType(null);
                }}
                className={`w-full py-4 rounded-2xl font-bold text-sm text-white active:scale-95 transition-all ${confirmType === 'app' ? 'bg-gray-800' : 'bg-red-500'}`}
              >
                {confirmType === 'app' ? 'プロトタイプ１に戻す' : 'はい、消去する'}
              </button>
              <button onClick={() => { setConfirmType(null); setPassword(''); setPassError(false); }} className="w-full py-3 bg-transparent text-gray-400 font-bold text-sm">キャンセル</button>
            </div>
          </div>
        </div>
      )}

      {showHistory && (
        <MasterListModal
          history={masterHistory}
          onSelect={(name, color, quantity) => { onAdd(name, color, quantity); setShowHistory(false); }}
          onDeleteHistoryItem={onDeleteHistoryItem}
          onUpdateHistoryOrder={onUpdateHistoryOrder}
          onClose={() => setShowHistory(false)}
          themeColor={themeColor}
        />
      )}
      {showSettings && <div className="fixed inset-0 z-40" onClick={() => setShowSettings(false)} />}
    </div>
  );
};

export default ShoppingListView;

import React, { useRef, useEffect, useState } from 'react';
import Sortable from 'sortablejs';
import { HistoryItem } from '../types';

interface Props {
  history: HistoryItem[];
  onSelect: (name: string, color: string, quantity?: string) => void;
  onDeleteHistoryItem: (name: string) => void;
  onUpdateHistoryOrder: (history: HistoryItem[]) => void;
  onClose: () => void;
  themeColor: string;
}

const MasterListModal: React.FC<Props> = ({ history, onSelect, onDeleteHistoryItem, onUpdateHistoryOrder, onClose, themeColor }) => {
  const gridRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);
  const [selectedItemName, setSelectedItemName] = useState<string | null>(null);
  const [quantity, setQuantity] = useState('');

  useEffect(() => {
    if (gridRef.current && history.length > 0) {
      sortableRef.current = new Sortable(gridRef.current, {
        animation: 150,
        ghostClass: 'opacity-20',
        delay: 100,
        delayOnTouchOnly: true,
        onEnd: (evt: any) => {
          const newHistory = [...history];
          const [movedItem] = newHistory.splice(evt.oldIndex, 1);
          newHistory.splice(evt.newIndex, 0, movedItem);
          onUpdateHistoryOrder(newHistory);
        },
      });
    }
    return () => {
      if (sortableRef.current) {
        sortableRef.current.destroy();
        sortableRef.current = null;
      }
    };
  }, [history, onUpdateHistoryOrder]);

  const handleConfirmAdd = (name: string, color: string) => {
    onSelect(name, color, quantity.trim());
    setSelectedItemName(null);
    setQuantity('');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center animate-fadeIn">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-md h-[75vh] rounded-t-[40px] sm:rounded-[40px] shadow-2xl overflow-hidden flex flex-col animate-slideUp">
        <div className="px-6 py-5 border-b flex items-center justify-between sticky top-0 bg-white z-10">
          <div>
            <h3 className="text-lg font-bold text-gray-800">過去の履歴から追加</h3>
            <p className="text-[10px] text-gray-400 font-bold tracking-wider">TAP TO INPUT QUANTITY</p>
          </div>
          <button onClick={onClose} className="w-10 h-10 rounded-full bg-gray-50 text-gray-400 flex items-center justify-center active:scale-90 transition-transform">
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 bg-gray-50/30">
          {history.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 py-12">
              <i className="fa-solid fa-clock-rotate-left text-4xl mb-4 opacity-20"></i>
              <p className="font-bold">履歴はまだありません</p>
            </div>
          ) : (
            <div ref={gridRef} className="grid grid-cols-2 gap-3 pb-8">
              {history.map((item, index) => (
                <div key={`${item.name}-${index}`} className="relative group overflow-visible">
                  {selectedItemName === item.name ? (
                    <div 
                      className="w-full p-3 border-2 rounded-2xl bg-white shadow-lg border-gray-200 animate-fadeIn z-20 space-y-2"
                      style={{ borderTopColor: item.color }}
                    >
                      <span className="block text-[10px] font-bold text-gray-400 truncate">{item.name}</span>
                      <input
                        autoFocus
                        type="text"
                        value={quantity}
                        onChange={(e) => setQuantity(e.target.value)}
                        placeholder="個数/単位を入力"
                        className="w-full px-2 py-2 text-xs border rounded-lg outline-none focus:border-gray-400 font-bold"
                        onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd(item.name, item.color)}
                      />
                      <div className="flex gap-1">
                        <button 
                          onClick={() => handleConfirmAdd(item.name, item.color)}
                          className="flex-1 py-2 bg-gray-800 text-white text-[10px] font-bold rounded-lg active:scale-95 transition-all shadow-sm"
                        >
                          追加
                        </button>
                        <button 
                          onClick={() => setSelectedItemName(null)}
                          className="px-2 py-2 bg-gray-100 text-gray-400 text-[10px] rounded-lg"
                        >
                          <i className="fa-solid fa-xmark"></i>
                        </button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <button
                        onClick={() => {
                          setSelectedItemName(item.name);
                          setQuantity('');
                        }}
                        className="w-full p-4 pr-10 text-left border border-gray-100 rounded-2xl active:scale-[0.98] transition-all flex items-center shadow-sm bg-white hover:border-gray-200"
                        style={{ borderLeft: `4px solid ${item.color || '#e5e7eb'}` }}
                      >
                        <span className="text-sm font-bold text-[#6b5e51] line-clamp-2 leading-tight">{item.name}</span>
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); onDeleteHistoryItem(item.name); }}
                        className="absolute right-1 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center text-gray-200 hover:text-red-400 transition-colors z-10"
                      >
                        <i className="fa-solid fa-trash-can text-[10px]"></i>
                      </button>
                    </>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
        <div className="p-5 border-t bg-white text-center">
          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
            <i className="fa-solid fa-hand-pointer mr-1"></i>
            タップして個数入力 / 長押しで並び替え
          </p>
        </div>
      </div>
    </div>
  );
};

export default MasterListModal;

import React, { useState, useRef, useEffect } from 'react';
import Sortable from 'sortablejs';
import { ShoppingItem, LocationId, HistoryItem } from '../types';
import MasterListModal from './MasterListModal';
import { GoogleGenAI, Type } from "@google/genai";

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: HistoryItem[];
  isSyncing?: boolean;
  onBack: () => void;
  onAdd: (name: string, color?: string, quantity?: string) => void;
  onToggle: (id: string) => void;
  onUpdateColor: (id: string, color: string) => void;
  onUpdateQuantity: (id: string, quantity: string) => void;
  onDelete: (id: string) => void;
  onUpdateOrder: (items: ShoppingItem[]) => void;
  onUpdateHistoryOrder: (history: HistoryItem[]) => void;
  onReset: () => void;
  onResetHistory: () => void;
  onResetApp: () => void;
  onDeleteHistoryItem: (name: string) => void;
}

const COLORS = [
  { id: 'white', value: '#ffffff', label: '標準' },
  { id: 'pink', value: '#ffecf0', label: 'さくら' },
  { id: 'blue', value: '#e3f2fd', label: 'そら' },
  { id: 'green', value: '#f1f8e9', label: 'わかば' },
];

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  isSyncing = false,
  onBack,
  onAdd,
  onToggle,
  onUpdateColor,
  onUpdateQuantity,
  onDelete,
  onUpdateOrder,
  onUpdateHistoryOrder,
  onReset,
  onResetHistory,
  onResetApp,
  onDeleteHistoryItem,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [quantityValue, setQuantityValue] = useState('');
  const [selectedColor, setSelectedColor] = useState('#ffffff');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [confirmType, setConfirmType] = useState<'list' | 'history' | 'app' | null>(null);
  const [password, setPassword] = useState('');
  const [passError, setPassError] = useState(false);

  // AI Mode States
  const [aiMode, setAiMode] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<{ name: string; quantity: string; selected: boolean }[]>([]);
  const [aiSelectedColor, setAiSelectedColor] = useState('#ffffff');

  // Item Edit States
  const [editingColorId, setEditingColorId] = useState<string | null>(null);
  const [editingQuantityId, setEditingQuantityId] = useState<string | null>(null);
  const [tempQuantity, setTempQuantity] = useState('');

  const recognitionRef = useRef<any>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    if (listRef.current && items.length > 0) {
      sortableRef.current = new Sortable(listRef.current, {
        animation: 150,
        ghostClass: 'opacity-20',
        delay: 100,
        delayOnTouchOnly: true,
        onEnd: (evt: any) => {
          const newItems = [...items];
          const [movedItem] = newItems.splice(evt.oldIndex, 1);
          newItems.splice(evt.newIndex, 0, movedItem);
          onUpdateOrder(newItems);
        },
      });
    }
    return () => {
      if (sortableRef.current) {
        sortableRef.current.destroy();
        sortableRef.current = null;
      }
    };
  }, [items, onUpdateOrder]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.lang = 'ja-JP';
      recognition.interimResults = false;

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onerror = () => setIsListening(false);

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputValue(transcript);
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, []);

  const handleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!recognitionRef.current) {
      alert('音声入力に対応していません');
      return;
    }

    if (isListening) {
      try {
        recognitionRef.current.stop();
      } catch (err) {
        console.error("Speech stop error:", err);
      }
    } else {
      try {
        recognitionRef.current.start();
      } catch (err) {
        console.error("Speech start error:", err);
        setIsListening(false);
      }
    }
  };

  const handleAiAction = async () => {
    if (!inputValue.trim()) return;

    setIsAiLoading(true);
    setAiSuggestions([]);

    try {
      if (!process.env.API_KEY) {
        throw new Error("APIキーが設定されていません。Vercelの環境変数を確認してください。");
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `料理名「${inputValue}」を作るために、一般的なスーパーで購入が必要な食材リストを教えてください。`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              ingredients: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING, description: '食材名' },
                    quantity: { type: Type.STRING, description: '目安の分量' }
                  },
                  required: ['name', 'quantity']
                }
              }
            },
            required: ['ingredients']
          }
        }
      });

      const responseText = response.text || '';
      // AIがMarkdownの装飾( ```json ... ``` )を付けて返した場合に備えて除去する処理
      const cleanJson = responseText.replace(/```json\n?|```/g, '').trim();

      const data = JSON.parse(cleanJson || '{"ingredients":[]}');
      setAiSuggestions(data.ingredients.map((ing: any) => ({ ...ing, selected: true })));
    } catch (e: any) {
      console.error("AI予測失敗の詳細:", e);
      alert(`食材の予測に失敗しました。\n原因: ${e.message || "不明なエラー"}\nコンソールログを確認してください。`);
    } finally {
      setIsAiLoading(false);
    }
  };

  const updateAiSuggestionQuantity = (index: number, newQty: string) => {
    const newSuggestions = [...aiSuggestions];
    newSuggestions[index].quantity = newQty;
    setAiSuggestions(newSuggestions);
  };

  const addSelectedAiItems = () => {
    const selectedItems = aiSuggestions.filter(s => s.selected);
    selectedItems.forEach(item => {
      onAdd(item.name, aiSelectedColor, item.quantity);
    });
    setAiSuggestions([]);
    setInputValue('');
    setAiMode(false);
  };

  const handleAdd = () => {
    if (aiMode) {
      handleAiAction();
      return;
    }
    if (inputValue.trim()) {
      onAdd(inputValue, selectedColor, quantityValue.trim());
      setInputValue('');
      setQuantityValue('');
      setSelectedColor('#ffffff');
    }
  };

  const handleAppReset = () => {
    if (password === 'hirake5ma') {
      onResetApp();
      setConfirmType(null);
      setPassword('');
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  };

  const saveQuantityEdit = (id: string) => {
    onUpdateQuantity(id, tempQuantity);
    setEditingQuantityId(null);
    setTempQuantity('');
  };

  return (
    <div className="flex flex-col h-full overflow-hidden relative" onClick={() => { setEditingColorId(null); setEditingQuantityId(null); }}>
      <header className="px-4 pt-6 pb-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <div className="flex items-center">
          <button onClick={onBack} className="text-gray-400 hover:text-gray-600 p-2">
            <i className="fa-solid fa-chevron-left text-xl"></i>
          </button>
          {isSyncing && (
            <div className="ml-1 text-blue-400 animate-pulse">
              <i className="fa-solid fa-cloud text-[10px]"></i>
            </div>
          )}
        </div>
        <div className="flex flex-col items-center">
          <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        </div>
        <div className="flex items-center gap-1">
          <button 
            onClick={(e) => { e.stopPropagation(); setConfirmType('list'); }}
            className="text-red-400 hover:text-red-600 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-red-50 transition-all border border-transparent active:border-red-100"
          >
            カゴ消去
          </button>
          <div className="relative">
            <button onClick={(e) => { e.stopPropagation(); setShowSettings(!showSettings); }} className="text-gray-300 hover:text-gray-500 p-2">
              <i className="fa-solid fa-ellipsis-vertical text-lg"></i>
            </button>
            {showSettings && (
              <div className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-xl border border-gray-100 py-2 z-50 animate-fadeIn overflow-hidden">
                <button 
                  onClick={() => { setConfirmType('history'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-gray-500 hover:bg-gray-50 flex items-center gap-3"
                >
                  <i className="fa-solid fa-clock-rotate-left w-4 text-center"></i>
                  履歴リストを空にする
                </button>
                <div className="border-t border-gray-50"></div>
                <button 
                  onClick={() => { setConfirmType('app'); setShowSettings(false); }}
                  className="w-full text-left px-4 py-3 text-xs text-red-400 hover:bg-red-50 flex items-center gap-3 font-bold"
                >
                  <i className="fa-solid fa-rotate-left w-4 text-center"></i>
                  全初期化 (プロトタイプ1)
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="p-6 bg-white shadow-sm space-y-4" onClick={(e) => e.stopPropagation()}>
        <div className="flex flex-col gap-3">
          <div className="flex items-center justify-between px-1">
            <div className="flex gap-4">
              {COLORS.map((color) => (
                <button
                  key={color.id}
                  onClick={() => setSelectedColor(color.value)}
                  className={`w-7 h-7 rounded-full border-2 transition-all shadow-sm flex items-center justify-center ${
                    selectedColor === color.value ? 'scale-110 border-gray-400' : 'border-transparent'
                  }`}
                  style={{ backgroundColor: color.value }}
                >
                  {selectedColor === color.value && <i className="fa-solid fa-check text-[10px] text-gray-400"></i>}
                </button>
              ))}
            </div>
            <button 
              onClick={() => {
                setAiMode(!aiMode);
                setAiSuggestions([]);
                setInputValue('');
              }}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[11px] font-bold transition-all border-2 ${
                aiMode ? 'bg-purple-500 border-purple-500 text-white shadow-md' : 'bg-white border-gray-100 text-gray-400'
              }`}
            >
              <i className={`fa-solid fa-wand-magic-sparkles ${aiMode ? 'animate-pulse' : ''}`}></i>
              {aiMode ? 'AIモードON' : 'AIモード'}
            </button>
          </div>

          <div className="space-y-2">
            <div className="relative flex items-center gap-2">
              <div className="relative flex-1">
                <input
                  type="text"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  placeholder={aiMode ? "作りたいメニューと何人前か入力" : "何を買いますか？"}
                  className={`w-full pl-4 pr-10 py-3 rounded-2xl border-2 outline-none transition-all ${
                    aiMode ? 'border-purple-100 focus:border-purple-300 bg-purple-50/20' : 'border-gray-100 focus:border-gray-200'
                  }`}
                />
                <button
                  onClick={handleVoiceInput}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-full transition-colors z-10 ${
                    isListening 
                      ? 'text-red-500 animate-pulse bg-red-50' 
                      : (aiMode ? 'text-purple-400 hover:text-purple-600' : 'text-gray-400 hover:text-gray-600')
                  }`}
                >
                  <i className="fa-solid fa-microphone"></i>
                </button>
              </div>
              <button
                onClick={handleAdd}
                disabled={isAiLoading}
                style={{ backgroundColor: aiMode ? '#a855f7' : themeColor }}
                className="w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg active:scale-90 transition-all shrink-0 disabled:opacity-50"
              >
                {isAiLoading ? (
                  <i className="fa-solid fa-circle-notch animate-spin text-xl"></i>
                ) : (
                  <i className={`fa-solid ${aiMode ? 'fa-magnifying-glass' : 'fa-plus'} text-xl`}></i>
                )}
              </button>
            </div>

            {!aiMode && (
              <div className="w-full">
                <input
                  type="text"
                  value={quantityValue}
                  onChange={(e) => setQuantityValue(e.target.value)}
                  placeholder="個数を入力（任意）"
                  className="w-full px-4 py-2.5 rounded-xl border-2 border-gray-50 focus:border-gray-100 bg-gray-50/30 outline-none transition-all text-sm"
                />
              </div>
            )}

            {/* AI Suggestions Panel */}
            {aiSuggestions.length > 0 && (
              <div className="bg-purple-50/50 rounded-2xl p-4 border border-purple-100 animate-fadeIn space-y-3 shadow-sm">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[11px] font-bold text-purple-600 tracking-wider">予測食材（個数編集可）</span>
                  <button onClick={() => setAiSuggestions([])} className="text-purple-300 hover:text-purple-500">
                    <i className="fa-solid fa-xmark"></i>
                  </button>
                </div>
                <div className="grid grid-cols-1 gap-2 max-h-48 overflow-y-auto pr-1">
                  {aiSuggestions.map((s, idx) => (
                    <div 
                      key={idx} 
                      className={`flex items-center gap-2 p-2 rounded-xl border transition-all ${
                        s.selected ? 'bg-white border-purple-200 shadow-sm' : 'bg-transparent border-transparent opacity-40'
                      }`}
                    >
                      <button
                        onClick={() => {
                          const newS = [...aiSuggestions];
                          newS[idx].selected = !newS[idx].selected;
                          setAiSuggestions(newS);
                        }}
                        className={`w-6 h-6 rounded-md border flex items-center justify-center transition-all shrink-0 ${
                          s.selected ? 'bg-purple-500 border-purple-500 text-white' : 'border-purple-200'
                        }`}
                      >
                        {s.selected && <i className="fa-solid fa-check text-[10px]"></i>}
                      </button>
                      <div className="flex-1 min-w-0">
                        <span className="text-sm font-bold text-gray-700 truncate block">{s.name}</span>
                      </div>
                      <input
                        type="text"
                        value={s.quantity}
                        onChange={(e) => updateAiSuggestionQuantity(idx, e.target.value)}
                        className="w-20 px-2 py-1 text-xs border rounded-lg outline-none focus:border-purple-300 text-right bg-purple-50/30 font-bold text-purple-600"
                        placeholder="分量"
                      />
                    </div>
                  ))}
                </div>

                <div className="pt-2 space-y-3">
                  <div className="flex items-center justify-center gap-3 bg-white/50 py-2 rounded-xl border border-purple-100">
                    <span className="text-[10px] font-bold text-gray-400">カードの色:</span>
                    {COLORS.map((color) => (
                      <button
                        key={color.id}
                        onClick={() => setAiSelectedColor(color.value)}
                        className={`w-6 h-6 rounded-full border-2 transition-all ${
                          aiSelectedColor === color.value ? 'scale-110 border-purple-400' : 'border-transparent'
                        }`}
                        style={{ backgroundColor: color.value }}
                      />
                    ))}
                  </div>
                  <button
                    onClick={addSelectedAiItems}
                    className="w-full py-3 bg-purple-600 text-white rounded-xl text-sm font-bold shadow-md active:scale-95 transition-all"
                  >
                    選択した食材を追加
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
        <button
          onClick={() => setShowHistory(true)}
          className="w-full py-2.5 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200 hover:bg-[#e9e5e0] transition-colors"
        >
          <i className="fa-solid fa-list-ul"></i>
          履歴リストから選ぶ
        </button>
      </div>

      <div ref={listRef} className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-300 pointer-events-none">
            <i className="fa-solid fa-basket-shopping text-4xl mb-4 opacity-30"></i>
            <p className="text-sm font-bold opacity-50">買い物依頼はありません</p>
          </div>
        ) : (
          items.map((item) => (
            <div
              key={item.id}
              className={`flex items-center gap-3 p-4 rounded-2xl shadow-sm border border-gray-100 cursor-grab active:cursor-grabbing relative ${
                item.completed ? 'opacity-60 grayscale-[0.5]' : ''
              }`}
              style={{ backgroundColor: item.color || '#ffffff' }}
            >
              <button
                onClick={(e) => { e.stopPropagation(); onToggle(item.id); }}
                className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all bg-white shrink-0 ${
                  item.completed ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200 text-transparent'
                }`}
              >
                <i className="fa-solid fa-check text-xs"></i>
              </button>
              <div className="flex-1 flex items-baseline justify-between gap-2 overflow-hidden">
                {editingQuantityId === item.id ? (
                  <div className="flex-1 flex gap-2 items-center" onClick={(e) => e.stopPropagation()}>
                    <input
                      autoFocus
                      type="text"
                      value={tempQuantity}
                      onChange={(e) => setTempQuantity(e.target.value)}
                      onBlur={() => saveQuantityEdit(item.id)}
                      onKeyDown={(e) => e.key === 'Enter' && saveQuantityEdit(item.id)}
                      className="w-full px-2 py-1 text-sm border-2 border-gray-200 rounded-lg outline-none focus:border-gray-400 bg-white font-bold"
                    />
                  </div>
                ) : (
                  <>
                    <span className={`text-[15px] font-bold transition-all truncate ${item.completed ? 'line-through text-gray-400 font-normal' : 'text-[#4a3f35]'}`}>
                      {item.name}
                      {item.quantity && (
                        <span className="ml-2 px-2 py-0.5 bg-white/50 rounded-lg text-xs font-bold text-gray-500">
                          {item.quantity}
                        </span>
                      )}
                    </span>
                    <span className="text-[10px] text-gray-500 font-normal shrink-0">{formatDate(item.createdAt)}</span>
                  </>
                )}
              </div>

              <div className="flex items-center gap-1 shrink-0">
                {/* Quantity edit button */}
                <button 
                  onClick={(e) => { e.stopPropagation(); setEditingQuantityId(item.id); setTempQuantity(item.quantity || ''); }}
                  className="text-gray-300 hover:text-gray-500 p-2 transition-colors"
                >
                  <i className="fa-solid fa-pen-to-square text-sm"></i>
                </button>

                {/* Color Picker Toggle */}
                <div className="relative">
                  <button 
                    onClick={(e) => { e.stopPropagation(); setEditingColorId(editingColorId === item.id ? null : item.id); }}
                    className="text-gray-300 hover:text-gray-500 p-2 transition-colors"
                  >
                    <i className="fa-solid fa-palette text-sm"></i>
                  </button>
                  {editingColorId === item.id && (
                    <div className="absolute right-0 bottom-full mb-2 bg-white p-2 rounded-xl shadow-xl border border-gray-100 flex gap-2 z-20 animate-fadeIn" onClick={(e) => e.stopPropagation()}>
                      {COLORS.map((c) => (
                        <button
                          key={c.id}
                          onClick={() => { onUpdateColor(item.id, c.value); setEditingColorId(null); }}
                          className={`w-6 h-6 rounded-full border border-gray-100 shadow-sm ${item.color === c.value ? 'ring-2 ring-gray-400' : ''}`}
                          style={{ backgroundColor: c.value }}
                        />
                      ))}
                    </div>
                  )}
                </div>

                <button onClick={(e) => { e.stopPropagation(); onDelete(item.id); }} className="text-gray-300 hover:text-red-400 p-2 transition-colors shrink-0">
                  <i className="fa-solid fa-trash-can text-sm"></i>
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {confirmType && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-fadeIn">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { setConfirmType(null); setPassword(''); setPassError(false); }} />
          <div className="relative bg-white w-full max-w-xs rounded-[32px] p-8 shadow-2xl text-center space-y-6">
            <div className={`w-14 h-14 rounded-full flex items-center justify-center mx-auto ${confirmType === 'app' ? 'bg-gray-100' : 'bg-red-50 text-red-500'}`}>
              <i className={`fa-solid ${confirmType === 'app' ? 'fa-lock' : 'fa-trash-can'} text-xl`}></i>
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-800 mb-2">
                {confirmType === 'list' ? '現在のカゴを空にしますか？' : confirmType === 'history' ? '過去の履歴をすべて消去しますか？' : 'プロトタイプ１に戻しますか？'}
              </h3>
              {confirmType === 'app' && (
                <>
                  <p className="text-[10px] text-gray-400 mb-4">初期状態（データなし）にリセットされます</p>
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => { setPassword(e.target.value); setPassError(false); }}
                    placeholder="パスワードを入力"
                    className={`w-full px-4 py-3 rounded-xl border-2 outline-none transition-all text-center ${passError ? 'border-red-300 bg-red-50' : 'border-gray-100 focus:border-gray-300'}`}
                  />
                  {passError && <p className="text-center text-[10px] text-red-500 mt-2 font-bold">パスワードが違います</p>}
                </>
              )}
            </div>
            <div className="flex flex-col gap-2">
              <button
                onClick={() => {
                  if (confirmType === 'list') onReset();
                  else if (confirmType === 'history') onResetHistory();
                  else if (confirmType === 'app') { handleAppReset(); return; }
                  setConfirmType(null);
                }}
                className={`w-full py-4 rounded-2xl font-bold text-sm text-white active:scale-95 transition-all ${confirmType === 'app' ? 'bg-gray-800' : 'bg-red-500'}`}
              >
                {confirmType === 'app' ? 'プロトタイプ１に戻す' : 'はい、消去する'}
              </button>
              <button onClick={() => { setConfirmType(null); setPassword(''); setPassError(false); }} className="w-full py-3 bg-transparent text-gray-400 font-bold text-sm">キャンセル</button>
            </div>
          </div>
        </div>
      )}

      {showHistory && (
        <MasterListModal
          history={masterHistory}
          onSelect={(name, color, quantity) => { onAdd(name, color, quantity); setShowHistory(false); }}
          onDeleteHistoryItem={onDeleteHistoryItem}
          onUpdateHistoryOrder={onUpdateHistoryOrder}
          onClose={() => setShowHistory(false)}
          themeColor={themeColor}
        />
      )}
      {showSettings && <div className="fixed inset-0 z-40" onClick={() => setShowSettings(false)} />}
    </div>
  );
};

