  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    return localStorage.getItem(AUTH_KEY) === 'true';
  });

  const [state, setState] = useState<AppState>(PROTOTYPE_2_STATE);
  const [isSyncing, setIsSyncing] = useState(false);

  const syncToCloud = async (newState: AppState) => {
    if (!db) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
      return;
    }

    setIsSyncing(true);
    try {
      const { currentLocation, ...dataToSync } = newState;
      await setDoc(doc(db, "shopping_lists", SHARED_DOC_ID), dataToSync);
    } catch (e) {
      console.error("クラウド保存失敗:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (!db || !isLoggedIn) return;

    setIsSyncing(true);
    const unsub = onSnapshot(doc(db, "shopping_lists", SHARED_DOC_ID), (docSnap) => {
      if (docSnap.exists()) {
        const cloudData = docSnap.data() as any;
        const sanitizedHistory = (cloudData.masterHistory || []).map((h: any) => 
          typeof h === 'string' ? { name: h, color: '#ffffff' } : h
        );

        setState(prev => ({
          ...cloudData,
          masterHistory: sanitizedHistory,
          currentLocation: prev.currentLocation
        }));
      } else {
        syncToCloud(PROTOTYPE_2_STATE);
      }
      setIsSyncing(false);
    }, (error) => {
      console.error("同期エラー:", error);
      setIsSyncing(false);
    });

    return () => unsub();
  }, [isLoggedIn]);

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem(AUTH_KEY, 'true');
  };

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string, color: string = '#ffffff', quantity: string = '') => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation || !name.trim()) return prev;

      const trimmedName = name.trim();
      const newItem: ShoppingItem = {
        id: crypto.randomUUID(),
        name: trimmedName,
        completed: false,
        createdAt: Date.now(),
        color: color,
        quantity: quantity,
      };

      const newHistory: HistoryItem[] = [
        { name: trimmedName, color },
        ...prev.masterHistory.filter(h => h.name !== trimmedName)
      ].slice(0, 100);

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [newItem, ...prev.lists[currentLocation]],
        },
        masterHistory: newHistory,
      };

      syncToCloud(newState);
      return newState;
    });
  }, []);

  const toggleItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, completed: !item.completed } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const updateItemColor = (id: string, color: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, color } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const updateItemQuantity = (id: string, quantity: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].map(item =>
            item.id === id ? { ...item, quantity } : item
          ),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const deleteItem = (id: string) => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;

      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: prev.lists[currentLocation].filter(item => item.id !== id),
        },
      };
      syncToCloud(newState);
      return newState;
    });
  };

  const updateListOrder = useCallback((items: ShoppingItem[]) => {
    setState(prev => {
      if (!prev.currentLocation) return prev;
      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [prev.currentLocation]: items,
        },
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const updateHistoryOrder = useCallback((newHistory: HistoryItem[]) => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: newHistory,
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const resetList = useCallback(() => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation) return prev;
      const newState = {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [],
        },
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const resetHistory = useCallback(() => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: [],
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const deleteHistoryItem = useCallback((name: string) => {
    setState(prev => {
      const newState = {
        ...prev,
        masterHistory: prev.masterHistory.filter(h => h.name !== name),
      };
      syncToCloud(newState);
      return newState;
    });
  }, []);

  const resetToPrototype2 = useCallback(async () => {
    await syncToCloud(PROTOTYPE_2_STATE);
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(AUTH_KEY);
    setState(PROTOTYPE_2_STATE);
    setIsLoggedIn(false);
  }, []);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
        <LoginScreen onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
      {!state.currentLocation ? (
        <LocationSelector 
          onSelect={setLocation} 
          onResetApp={resetToPrototype2} 
        />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          isSyncing={isSyncing}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onUpdateColor={updateItemColor}
          onUpdateQuantity={updateItemQuantity}
          onDelete={deleteItem}
          onUpdateOrder={updateListOrder}
          onUpdateHistoryOrder={updateHistoryOrder}
          onReset={resetList}
          onResetHistory={resetHistory}
          onResetApp={resetToPrototype2}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import Sortable from 'sortablejs';
import { ShoppingItem, LocationId, HistoryItem } from '../types';
import MasterListModal from './MasterListModal';
import { GoogleGenAI, Type } from "@google/genai";

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  masterHistory: HistoryItem[];
  isSyncing?: boolean;
  onBack: () => void;
  onAdd: (name: string, color?: string, quantity?: string) => void;
  onToggle: (id: string) => void;
  onUpdateColor: (id: string, color: string) => void;
  onUpdateQuantity: (id: string, quantity: string) => void;
  onDelete: (id: string) => void;
  onUpdateOrder: (items: ShoppingItem[]) => void;
  onUpdateHistoryOrder: (history: HistoryItem[]) => void;
  onReset: () => void;
  onResetHistory: () => void;
  onResetApp: () => void;
  onDeleteHistoryItem: (name: string) => void;
}

const COLORS = [
  { id: 'white', value: '#ffffff', label: '標準' },
  { id: 'pink', value: '#ffecf0', label: 'さくら' },
  { id: 'blue', value: '#e3f2fd', label: 'そら' },
  { id: 'green', value: '#f1f8e9', label: 'わかば' },
];

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  masterHistory,
  isSyncing = false,
  onBack,
  onAdd,
  onToggle,
  onUpdateColor,
  onUpdateQuantity,
  onDelete,
  onUpdateOrder,
  onUpdateHistoryOrder,
  onReset,
  onResetHistory,
  onResetApp,
  onDeleteHistoryItem,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [quantityValue, setQuantityValue] = useState('');
  const [selectedColor, setSelectedColor] = useState('#ffffff');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [confirmType, setConfirmType] = useState<'list' | 'history' | 'app' | null>(null);
  const [password, setPassword] = useState('');

  const [aiMode, setAiMode] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<{ name: string; quantity: string; selected: boolean }[]>([]);

  const [editingQuantityId, setEditingQuantityId] = useState<string | null>(null);
  const [tempQuantity, setTempQuantity] = useState('');

  const recognitionRef = useRef<any>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    if (listRef.current && items.length > 0) {
      sortableRef.current = new Sortable(listRef.current, {
        animation: 150,
        ghostClass: 'opacity-20',
        delay: 100,
        delayOnTouchOnly: true,
        onEnd: (evt: any) => {
          const newItems = [...items];
          const [movedItem] = newItems.splice(evt.oldIndex, 1);
          newItems.splice(evt.newIndex, 0, movedItem);
          onUpdateOrder(newItems);
        },
      });
    }
    return () => sortableRef.current?.destroy();
  }, [items, onUpdateOrder]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.lang = 'ja-JP';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        setInputValue(event.results[0][0].transcript);
        setIsListening(false);
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const handleVoiceInput = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!recognitionRef.current) return;
    isListening ? recognitionRef.current.stop() : recognitionRef.current.start();
  };

  const handleAiAction = async () => {
    if (!inputValue.trim()) return;
    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `料理名「${inputValue}」を作るための食材リストを教えてください。`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              ingredients: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    quantity: { type: Type.STRING }
                  },
                  required: ['name', 'quantity']
                }
              }
            },
            required: ['ingredients']
          }
        }
      });
      const data = JSON.parse(response.text?.trim() || '{"ingredients":[]}');
      setAiSuggestions(data.ingredients.map((ing: any) => ({ ...ing, selected: true })));
    } catch (e: any) {
      alert(`AI予測エラー: ${e.message}`);
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleAdd = () => {
    if (aiMode) { handleAiAction(); return; }
    if (inputValue.trim()) {
      onAdd(inputValue, selectedColor, quantityValue.trim());
      setInputValue('');
      setQuantityValue('');
      setSelectedColor('#ffffff');
    }
  };

  const saveQuantityEdit = (id: string) => {
    onUpdateQuantity(id, tempQuantity);
    setEditingQuantityId(null);
  };

  return (
    <div className="flex flex-col h-full overflow-hidden relative" onClick={() => setEditingQuantityId(null)}>
      <header className="px-4 pt-6 pb-4 flex items-center justify-between bg-white border-b sticky top-0 z-10">
        <button onClick={onBack} className="text-gray-400 p-2"><i className="fa-solid fa-chevron-left text-xl"></i></button>
        <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        <div className="flex items-center gap-1">
          <button onClick={() => setConfirmType('list')} className="text-red-400 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-red-50 transition-all">カゴ消去</button>
          <button onClick={() => setShowSettings(!showSettings)} className="text-gray-300 p-2"><i className="fa-solid fa-ellipsis-vertical text-lg"></i></button>
          {showSettings && (
            <div className="absolute right-0 mt-12 w-56 bg-white rounded-2xl shadow-xl border p-2 z-50">
              <button onClick={() => { setConfirmType('history'); setShowSettings(false); }} className="w-full text-left px-4 py-3 text-xs text-gray-500 hover:bg-gray-50 flex items-center gap-3"><i className="fa-solid fa-clock-rotate-left"></i>履歴を空にする</button>
              <button onClick={() => { setConfirmType('app'); setShowSettings(false); }} className="w-full text-left px-4 py-3 text-xs text-red-400 hover:bg-red-50 flex items-center gap-3 font-bold"><i className="fa-solid fa-rotate-left"></i>全初期化 (P2)</button>
            </div>
          )}
        </div>
      </header>

      <div className="p-6 bg-white space-y-4 shadow-sm">
        <div className="flex items-center justify-between px-1">
          <div className="flex gap-4">
            {COLORS.map((c) => (
              <button key={c.id} onClick={() => setSelectedColor(c.value)} className={`w-7 h-7 rounded-full border-2 ${selectedColor === c.value ? 'scale-110 border-gray-400' : 'border-transparent'}`} style={{ backgroundColor: c.value }} />
            ))}
          </div>
          <button onClick={() => { setAiMode(!aiMode); setAiSuggestions([]); setInputValue(''); }} className={`px-3 py-1.5 rounded-full text-[11px] font-bold border-2 ${aiMode ? 'bg-purple-500 border-purple-500 text-white' : 'text-gray-400 border-gray-100'}`}>
            <i className="fa-solid fa-wand-magic-sparkles mr-1"></i>{aiMode ? 'AI ON' : 'AI予測'}
          </button>
        </div>

        <div className="space-y-2">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <input value={inputValue} onChange={(e) => setInputValue(e.target.value)} placeholder={aiMode ? "料理名を入力" : "何を買いますか？"} className="w-full pl-4 pr-10 py-3 rounded-2xl border-2 border-gray-100 outline-none" />
              <button onClick={handleVoiceInput} className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 ${isListening ? 'text-red-500' : 'text-gray-400'}`}><i className="fa-solid fa-microphone"></i></button>
            </div>
            <button onClick={handleAdd} disabled={isAiLoading} style={{ backgroundColor: aiMode ? '#a855f7' : themeColor }} className="w-12 h-12 rounded-2xl text-white flex items-center justify-center shadow-lg active:scale-90 transition-all shrink-0">
              {isAiLoading ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <i className={`fa-solid ${aiMode ? 'fa-magnifying-glass' : 'fa-plus'}`}></i>}
            </button>
          </div>
          {!aiMode && <input value={quantityValue} onChange={(e) => setQuantityValue(e.target.value)} placeholder="個数/単位（任意）" className="w-full px-4 py-2.5 rounded-xl border-2 border-gray-50 text-sm outline-none" />}

          {aiSuggestions.length > 0 && (
            <div className="bg-purple-50 rounded-2xl p-4 border border-purple-100 space-y-3">
              <div className="max-h-48 overflow-y-auto space-y-2">
                {aiSuggestions.map((s, idx) => (
                  <div key={idx} className="flex items-center gap-2 p-2 bg-white rounded-xl border border-purple-200">
                    <button onClick={() => { const ns = [...aiSuggestions]; ns[idx].selected = !ns[idx].selected; setAiSuggestions(ns); }} className={`w-5 h-5 rounded border flex items-center justify-center ${s.selected ? 'bg-purple-500 text-white' : 'border-purple-200'}`}>{s.selected && <i className="fa-solid fa-check text-[10px]"></i>}</button>
                    <span className="flex-1 text-sm font-bold text-gray-700">{s.name}</span>
                    <input value={s.quantity} onChange={(e) => { const ns = [...aiSuggestions]; ns[idx].quantity = e.target.value; setAiSuggestions(ns); }} className="w-16 px-2 py-1 text-xs border rounded-lg text-right font-bold" />
                  </div>
                ))}
              </div>
              <button onClick={() => { aiSuggestions.filter(s => s.selected).forEach(i => onAdd(i.name, '#ffffff', i.quantity)); setAiSuggestions([]); setInputValue(''); setAiMode(false); }} className="w-full py-3 bg-purple-600 text-white rounded-xl text-sm font-bold">追加する</button>
            </div>
          )}
        </div>
        <button onClick={() => setShowHistory(true)} className="w-full py-2.5 bg-[#f3f0ec] text-[#8b7d6b] rounded-xl text-sm font-bold flex items-center justify-center gap-2 border border-gray-200"><i className="fa-solid fa-list-ul"></i>履歴から選ぶ</button>
      </div>

      <div ref={listRef} className="flex-1 overflow-y-auto p-6 space-y-3 pb-24">
        {items.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-gray-300 opacity-50"><i className="fa-solid fa-basket-shopping text-4xl mb-4"></i><p className="text-sm font-bold">買い物依頼はありません</p></div>
        ) : (
          items.map((item) => (
            <div key={item.id} className="flex items-center gap-3 p-4 rounded-2xl shadow-sm border border-gray-100" style={{ backgroundColor: item.color }}>
              <button onClick={() => onToggle(item.id)} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${item.completed ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200 text-transparent'}`}><i className="fa-solid fa-check text-xs"></i></button>
              <div className="flex-1 overflow-hidden" onClick={(e) => e.stopPropagation()}>
                {editingQuantityId === item.id ? (
                  <input autoFocus value={tempQuantity} onChange={(e) => setTempQuantity(e.target.value)} onBlur={() => saveQuantityEdit(item.id)} className="w-full px-2 py-1 text-sm border-2 rounded-lg bg-white" />
                ) : (
                  <div className="flex items-baseline gap-2">
                    <span className={`text-[15px] font-bold truncate ${item.completed ? 'line-through text-gray-400' : ''}`}>{item.name}</span>
                    {item.quantity && <span className="text-xs text-gray-500 font-bold bg-white/50 px-2 rounded-lg">{item.quantity}</span>}
                  </div>
                )}
              </div>
              <div className="flex items-center gap-1">
                <button onClick={(e) => { e.stopPropagation(); setEditingQuantityId(item.id); setTempQuantity(item.quantity || ''); }} className="text-gray-300 p-2"><i className="fa-solid fa-pen-to-square text-sm"></i></button>
                <button onClick={() => onDelete(item.id)} className="text-gray-300 p-2"><i className="fa-solid fa-trash-can text-sm"></i></button>
              </div>
            </div>
          ))
        )}
      </div>

      {confirmType && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 animate-fadeIn">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setConfirmType(null)} />
          <div className="relative bg-white w-full max-w-xs rounded-[32px] p-8 text-center space-y-6">
            <h3 className="text-lg font-bold">{confirmType === 'app' ? 'プロトタイプ２に戻す？' : '実行しますか？'}</h3>
            {confirmType === 'app' && <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="パスワード" className="w-full px-4 py-3 border-2 rounded-xl text-center outline-none" />}
            <div className="flex flex-col gap-2">
              <button onClick={() => { 
                if (confirmType === 'list') onReset(); 
                else if (confirmType === 'history') onResetHistory(); 
                else if (confirmType === 'app' && password === 'hirake5ma') onResetApp();
                setConfirmType(null); setPassword('');
              }} className="w-full py-4 bg-red-500 text-white rounded-2xl font-bold">実行</button>
              <button onClick={() => setConfirmType(null)} className="w-full py-3 text-gray-400 font-bold">中止</button>
            </div>
          </div>
        </div>
      )}

      {showHistory && <MasterListModal history={masterHistory} onSelect={(n, c) => { onAdd(n, c); setShowHistory(false); }} onDeleteHistoryItem={onDeleteHistoryItem} onUpdateHistoryOrder={onUpdateHistoryOrder} onClose={() => setShowHistory(false)} themeColor={themeColor} />}
    </div>
  );
};

export default ShoppingListView;

import React, { useRef, useEffect } from 'react';
import Sortable from 'sortablejs';
import { HistoryItem } from '../types';

interface Props {
  history: HistoryItem[];
  onSelect: (name: string, color: string) => void;
  onDeleteHistoryItem: (name: string) => void;
  onUpdateHistoryOrder: (history: HistoryItem[]) => void;
  onClose: () => void;
  themeColor: string;
}

const MasterListModal: React.FC<Props> = ({ history, onSelect, onDeleteHistoryItem, onUpdateHistoryOrder, onClose }) => {
  const gridRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);

  useEffect(() => {
    if (gridRef.current && history.length > 0) {
      sortableRef.current = new Sortable(gridRef.current, {
        animation: 150,
        ghostClass: 'opacity-20',
        delay: 100,
        delayOnTouchOnly: true,
        onEnd: (evt: any) => {
          const newHistory = [...history];
          const [movedItem] = newHistory.splice(evt.oldIndex, 1);
          newHistory.splice(evt.newIndex, 0, movedItem);
          onUpdateHistoryOrder(newHistory);
        },
      });
    }
    return () => sortableRef.current?.destroy();
  }, [history, onUpdateHistoryOrder]);

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center animate-fadeIn">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-md h-[75vh] rounded-t-[40px] sm:rounded-[40px] shadow-2xl overflow-hidden flex flex-col">
        <div className="px-6 py-5 border-b flex items-center justify-between sticky top-0 bg-white z-10">
          <h3 className="text-lg font-bold text-gray-800">履歴リスト</h3>
          <button onClick={onClose} className="w-10 h-10 rounded-full bg-gray-50 text-gray-400 flex items-center justify-center"><i className="fa-solid fa-xmark"></i></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 bg-gray-50/30">
          <div ref={gridRef} className="grid grid-cols-2 gap-3 pb-8">
            {history.map((item, index) => (
              <div key={`${item.name}-${index}`} className="relative group">
                <button
                  onClick={() => onSelect(item.name, item.color)}
                  className="w-full p-4 pr-10 text-left border border-gray-100 rounded-2xl bg-white shadow-sm active:scale-95 transition-all flex flex-col"
                  style={{ borderLeft: `4px solid ${item.color}` }}
                >
                  <span className="text-sm font-bold text-[#6b5e51] line-clamp-2">{item.name}</span>
                </button>
                <button
                  onClick={(e) => { e.stopPropagation(); onDeleteHistoryItem(item.name); }}
                  className="absolute right-1 top-1/2 -translate-y-1/2 w-8 h-8 text-gray-200 hover:text-red-400"
                >
                  <i className="fa-solid fa-trash-can text-[10px]"></i>
                </button>
              </div>
            ))}
          </div>
        </div>
        <div className="p-5 border-t bg-white text-center">
          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">タップで追加 / 長押しで並び替え</p>
        </div>
      </div>
    </div>
  );
};

export default MasterListModal;

export type LocationId = 'slowlife1' | 'slowlife2';

export interface HistoryItem {
  name: string;
  color: string;
}

export interface ShoppingItem {
  id: string;
  name: string;
  completed: boolean;
  color: string;
  quantity?: string;
}

export interface AppState {
  currentLocation: LocationId | null;
  lists: Record<LocationId, ShoppingItem[]>;
  history: HistoryItem[];
}

import React, { useState, useEffect, useCallback } from 'react';
import { LocationId, ShoppingItem, AppState, HistoryItem } from './types';
import LocationSelector from './components/LocationSelector';
import ShoppingListView from './components/ShoppingListView';

const STORAGE_KEY = 'slow_life_shopping_data_v1';

const INITIAL_STATE: AppState = {
  currentLocation: null,
  lists: {
    slowlife1: [],
    slowlife2: [],
  },
  history: [],
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : INITIAL_STATE;
  });

  // 保存処理
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const setLocation = (location: LocationId | null) => {
    setState(prev => ({ ...prev, currentLocation: location }));
  };

  const addItem = useCallback((name: string, color: string = '#ffffff', quantity: string = '') => {
    setState(prev => {
      const { currentLocation } = prev;
      if (!currentLocation || !name.trim()) return prev;

      const newItem: ShoppingItem = {
        id: crypto.randomUUID(),
        name: name.trim(),
        completed: false,
        color: color,
        quantity: quantity,
      };

      // 履歴の更新（重複削除して先頭へ）
      const newHistory = [
        { name: name.trim(), color },
        ...prev.history.filter(h => h.name !== name.trim())
      ].slice(0, 50);

      return {
        ...prev,
        lists: {
          ...prev.lists,
          [currentLocation]: [newItem, ...prev.lists[currentLocation]],
        },
        history: newHistory,
      };
    });
  }, []);

  const toggleItem = (id: string) => {
    setState(prev => {
      const loc = prev.currentLocation;
      if (!loc) return prev;
      return {
        ...prev,
        lists: {
          ...prev.lists,
          [loc]: prev.lists[loc].map(item =>
            item.id === id ? { ...item, completed: !item.completed } : item
          ),
        },
      };
    });
  };

  const deleteItem = (id: string) => {
    setState(prev => {
      const loc = prev.currentLocation;
      if (!loc) return prev;
      return {
        ...prev,
        lists: {
          ...prev.lists,
          [loc]: prev.lists[loc].filter(item => item.id !== id),
        },
      };
    });
  };

  const updateOrder = (items: ShoppingItem[]) => {
    setState(prev => {
      if (!prev.currentLocation) return prev;
      return {
        ...prev,
        lists: { ...prev.lists, [prev.currentLocation]: items },
      };
    });
  };

  const resetList = () => {
    setState(prev => {
      if (!prev.currentLocation) return prev;
      return {
        ...prev,
        lists: { ...prev.lists, [prev.currentLocation]: [] },
      };
    });
  };

  const deleteHistoryItem = (name: string) => {
    setState(prev => ({
      ...prev,
      history: prev.history.filter(h => h.name !== name)
    }));
  };

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col">
      {!state.currentLocation ? (
        <LocationSelector onSelect={setLocation} />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          history={state.history}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onToggle={toggleItem}
          onDelete={deleteItem}
          onUpdateOrder={updateOrder}
          onReset={resetList}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

export default App;

