import React, { useState, useRef, useEffect } from 'react';
import Sortable from 'sortablejs';
import { ShoppingItem, LocationId, HistoryItem } from '../types';
import MasterListModal from './MasterListModal';

interface Props {
  locationId: LocationId;
  items: ShoppingItem[];
  history: HistoryItem[];
  onBack: () => void;
  onAdd: (name: string, color?: string, quantity?: string) => void;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onUpdateOrder: (items: ShoppingItem[]) => void;
  onReset: () => void;
  onDeleteHistoryItem: (name: string) => void;
}

const COLORS = [
  { value: '#ffffff', label: '標準' },
  { value: '#ffecf0', label: 'さくら' },
  { value: '#e3f2fd', label: 'そら' },
  { value: '#f1f8e9', label: 'わかば' },
];

const ShoppingListView: React.FC<Props> = ({
  locationId,
  items,
  history,
  onBack,
  onAdd,
  onToggle,
  onDelete,
  onUpdateOrder,
  onReset,
  onDeleteHistoryItem,
}) => {
  const [inputValue, setInputValue] = useState('');
  const [quantityValue, setQuantityValue] = useState('');
  const [selectedColor, setSelectedColor] = useState('#ffffff');
  const [isListening, setIsListening] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const recognitionRef = useRef<any>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const sortableRef = useRef<any>(null);

  const themeColor = locationId === 'slowlife1' ? '#8dad82' : '#d4a373';
  const locationName = locationId === 'slowlife1' ? 'すろーらいふ 1' : 'すろーらいふ 2';

  useEffect(() => {
    if (listRef.current && items.length > 0) {
      sortableRef.current = new Sortable(listRef.current, {
        animation: 150,
        handle: '.drag-handle',
        onEnd: (evt: any) => {
          const newItems = [...items];
          const [movedItem] = newItems.splice(evt.oldIndex, 1);
          newItems.splice(evt.newIndex, 0, movedItem);
          onUpdateOrder(newItems);
        },
      });
    }
    return () => sortableRef.current?.destroy();
  }, [items]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.lang = 'ja-JP';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        setInputValue(event.results[0][0].transcript);
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const handleVoiceInput = () => {
    if (!recognitionRef.current) return;
    isListening ? recognitionRef.current.stop() : recognitionRef.current.start();
  };

  const handleAdd = () => {
    if (inputValue.trim()) {
      onAdd(inputValue, selectedColor, quantityValue.trim());
      setInputValue('');
      setQuantityValue('');
      setSelectedColor('#ffffff');
    }
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <header className="px-4 py-4 flex items-center justify-between bg-white border-b">
        <button onClick={onBack} className="text-gray-400 p-2"><i className="fa-solid fa-chevron-left text-xl"></i></button>
        <h2 className="text-lg font-bold" style={{ color: themeColor }}>{locationName}</h2>
        <button onClick={() => confirm('リストを空にしますか？') && onReset()} className="text-red-400 text-xs font-bold px-3 py-1">消去</button>
      </header>

      <div className="p-6 bg-white space-y-4 shadow-sm">
        <div className="flex gap-4 mb-2">
          {COLORS.map((c) => (
            <button 
              key={c.value} 
              onClick={() => setSelectedColor(c.value)} 
              className={`w-7 h-7 rounded-full border-2 ${selectedColor === c.value ? 'border-gray-400' : 'border-transparent'}`} 
              style={{ backgroundColor: c.value }} 
            />
          ))}
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <input 
              value={inputValue} 
              onChange={(e) => setInputValue(e.target.value)} 
              placeholder="何を買いますか？" 
              className="w-full pl-4 pr-10 py-3 rounded-2xl border-2 border-gray-100 outline-none focus:border-gray-200" 
            />
            <button onClick={handleVoiceInput} className={`absolute right-3 top-1/2 -translate-y-1/2 ${isListening ? 'text-red-500' : 'text-gray-300'}`}>
              <i className="fa-solid fa-microphone"></i>
            </button>
          </div>
          <button onClick={handleAdd} style={{ backgroundColor: themeColor }} className="w-12 h-12 rounded-2xl text-white shadow-lg active:scale-90 transition-all">
            <i className="fa-solid fa-plus"></i>
          </button>
        </div>
        <input 
          value={quantityValue} 
          onChange={(e) => setQuantityValue(e.target.value)} 
          placeholder="個数/単位（任意）" 
          className="w-full px-4 py-2 rounded-xl border-2 border-gray-50 text-sm" 
        />
        <button onClick={() => setShowHistory(true)} className="w-full py-2 bg-gray-50 text-gray-400 rounded-xl text-xs font-bold border border-gray-100">
          <i className="fa-solid fa-clock-rotate-left mr-2"></i>履歴から追加
        </button>
      </div>

      <div ref={listRef} className="flex-1 overflow-y-auto p-6 space-y-3">
        {items.map((item) => (
          <div key={item.id} className="flex items-center gap-3 p-4 rounded-2xl shadow-sm border border-gray-100" style={{ backgroundColor: item.color }}>
            <div className="drag-handle text-gray-200"><i className="fa-solid fa-grip-vertical"></i></div>
            <button onClick={() => onToggle(item.id)} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${item.completed ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200 text-transparent'}`}>
              <i className="fa-solid fa-check text-xs"></i>
            </button>
            <div className="flex-1">
              <span className={`font-bold ${item.completed ? 'line-through text-gray-400' : ''}`}>{item.name}</span>
              {item.quantity && <span className="ml-2 text-xs text-gray-500 bg-white/50 px-2 rounded-lg">{item.quantity}</span>}
            </div>
            <button onClick={() => onDelete(item.id)} className="text-gray-200 hover:text-red-300 transition-colors"><i className="fa-solid fa-trash-can"></i></button>
          </div>
        ))}
      </div>

      {showHistory && (
        <MasterListModal 
          history={history} 
          onSelect={(n, c) => { onAdd(n, c); setShowHistory(false); }} 
          onDeleteHistoryItem={onDeleteHistoryItem} 
          onClose={() => setShowHistory(false)} 
        />
      )}
    </div>
  );
};

