    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-[#fdfaf6] text-[#4a3f35] shadow-xl flex flex-col relative overflow-hidden">
      {!state.currentLocation ? (
        <LocationSelector onSelect={setLocation} />
      ) : (
        <ShoppingListView
          locationId={state.currentLocation}
          items={state.lists[state.currentLocation]}
          masterHistory={state.masterHistory}
          isSyncing={isSyncing}
          onBack={() => setLocation(null)}
          onAdd={addItem}
          onUpdateItem={updateItem}
          onToggle={toggleItem}
          onDelete={deleteItem}
          onUpdateOrder={updateOrder}
          onUpdateHistoryOrder={updateHistoryOrder}
          onReset={resetList}
          onDeleteHistoryItem={deleteHistoryItem}
        />
      )}
    </div>
  );
};

export default App;

payload.text:
「カゴ消去」ボタンの処理は、主に以下の2つのファイルに分かれて記述されています。

### 1. ボタンの見た目と実行（UI側）
**ファイル名：`components/ShoppingListView.tsx`**
138行目付近のヘッダー部分にボタンがあります。

```tsx
<button 
  onClick={() => confirm('カゴを空にしますか？') && onReset()} 
  className="text-red-400 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-red-50 transition-all"
>
  カゴ消去
</button>
```
*   **動作**: クリックするとブラウザの確認ダイアログ（`confirm`）が表示されます。
*   **実行**: 「OK」を押すと、親コンポーネントから渡された `onReset` 関数が実行されます。

---

### 2. 実際のデータ消去処理（ロジック側）
**ファイル名：`App.tsx`**
162行目付近にある `resetList` という関数がその実体です。

```tsx
const resetList = () => {
  setState(prev => {
    // 現在表示されている拠点のみを空にする
    if (!prev.currentLocation) return prev;
    const newState = {
      ...prev,
      lists: {
        ...prev.lists,
        [prev.currentLocation]: [], // ここでリストを空（[]）にしています
      },
    };
    syncToCloud(newState); // クラウド（Firebase）に反映
    return newState;
  });
};
```
*   **動作**: `currentLocation`（現在選んでいる拠点）のリストだけを `[]`（空配列）に書き換えます。
*   **同期**: `syncToCloud` を呼び出すことで、他のスマホやPCで見ているリストも同時に空になるようになっています。

もし「拠点1・2を同時に消去したい」などの変更を行いたい場合は、この `App.tsx` の `resetList` 内の処理を書き換えることになります。

