          ))
        )}
      </div>

      {showHistory && (
        <MasterListModal 
          history={masterHistory} 
          onSelect={(n, c, q) => { onAdd(n, c, q); setShowHistory(false); }} 
          onDeleteHistoryItem={onDeleteHistoryItem} 
          onUpdateHistoryOrder={onUpdateHistoryOrder}
          onClose={() => setShowHistory(false)} 
        />
      )}
